function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;}
function hydrateIcons(el=document){$$('[data-icon]',el).forEach(n=>{n.innerHTML=icon(n.dataset.icon);n.removeAttribute('data-icon');});}
function badge(t){if(!t.is_outlier&&state.result?.meta?.annual_comparison_available===false)return '<span class="badge badge-stable">年次未判定</span>';return `<span class="badge badge-${e(t.status)}">${t.status==='emerging'?'↗ ':''}${e(statuses[t.status]||t.status)}</span>`;}
function isUnclassified(topic){return Boolean(topic?.is_outlier||topic?.status==='unclassified');}
function classifiedTopics(){return (state.result?.topics||[]).filter(t=>!isUnclassified(t));}
function unclassifiedPaperCount(){return (state.result?.topics||[]).filter(isUnclassified).reduce((sum,t)=>sum+Number(t.count||0),0);}
function topicPaint(topic){return isUnclassified(topic)?'#8190a3':color(topic?.color);}
function topicModelName(value){return {kmeans:'K-means',nmf:'NMF',lda:'LDA',bertopic:'BERTopic'}[String(value||'kmeans')]||String(value);}
function mapRepresentationLabel(meta=state.result?.meta||{}){const repr=meta.map_representation;const labels={nmf_topic_distribution:'NMFテーマ分布',lda_topic_distribution:'LDAテーマ分布',sbert_embeddings:'SBERT埋め込み',tfidf:'TF-IDF'};if(labels[repr])return labels[repr];if(meta.topic_model==='nmf')return 'NMFテーマ分布';if(meta.topic_model==='lda')return 'LDAテーマ分布';return ['sbert','transformer'].includes(meta.embedding)?'SBERT埋め込み':'TF-IDF';}
function actualEmbeddingLabel(meta=state.result?.meta||{}){if(meta.topic_model==='lda')return '単語カウント';if(meta.topic_model==='nmf')return 'TF-IDF';if(['sbert','transformer'].includes(meta.embedding)||meta.map_representation==='sbert_embeddings'){const model=String(meta.embedding_model||meta.sbert_model||'').toLowerCase();return model.includes('mpnet')?'SBERT / MPNet':model.includes('minilm')?'SBERT / MiniLM':'SBERT';}return 'TF-IDF';}
function analysisMethodLabel(meta=state.result?.meta||{}){return `${topicModelName(meta.topic_model)} · ${actualEmbeddingLabel(meta)}`;}
function sbertAvailable(){return Boolean(state.status?.sbert_available??state.status?.transformer_available);}
function selectedTopicAvailable(id){const entry=state.status?.topic_models?.find(m=>m.id===id);return entry?entry.available!==false:id!=='bertopic';}
function updateModelCatalog(){const models=state.status?.topic_models||[];$$('#topic-model option').forEach(option=>{const entry=models.find(m=>m.id===option.value);option.disabled=!selectedTopicAvailable(option.value);if(entry?.label)option.textContent=entry.label;});const presets=state.status?.sbert_models;if(Array.isArray(presets)&&presets.length){const selected=$('#sbert-model').value;$('#sbert-model').innerHTML=presets.map(m=>`<option value="${e(m.id)}">${e(m.label||m.id)}</option>`).join('');$('#sbert-model').value=presets.some(m=>m.id===selected)?selected:presets.some(m=>m.id==='mpnet')?'mpnet':presets[0].id;}$('#embedding option[value="sbert"]').disabled=!sbertAvailable();syncModelControls();}
function syncModelControls(){const method=$('#topic-model').value,counts=['nmf','lda'].includes(method),bert=method==='bertopic',embedding=$('#embedding');if(counts)embedding.value='tfidf';else if(bert)embedding.value='sbert';else embedding.value=state.kmeansEmbedding;embedding.disabled=counts||bert;$('#embedding option[value="tfidf"]').textContent=method==='lda'?'単語カウント · LDA入力':'TF-IDF · 語の重要度で表現';const sbert=embedding.value==='sbert';$('#sbert-model-field').hidden=!sbert;$('#sbert-model').disabled=!sbert;$('#min-topic-size-field').hidden=!bert;$('#min-topic-size').disabled=!bert;$('#min-topic-size').required=bert;$('#topic-count-label').textContent=bert?'テーマ数上限の目安（縮約）':'テーマ数';const descriptions={kmeans:'選択した文章表現の近さに基づいて、指定した数のグループへ分類します。TF-IDFとSBERTのどちらでも利用できます。',nmf:'TF-IDF行列を非負値行列分解（NMF）し、語のまとまりからテーマを抽出します。文章表現はTF-IDFに固定し、マップにはNMFのテーマ分布を使います。',lda:'単語カウントに確率的トピックモデル（LDA）を適用します。語彙ベースの処理に固定し、テーマ推定にはTF-IDF値ではなく語の出現数、マップにはLDAのテーマ分布を使います。',bertopic:'SBERTの意味表現からテーマを自動検出します。テーマ数は縮約するときの上限の目安で、実際の検出数と異なる場合があります。まとまらない論文は未分類として残し、注目ランキング・予測から除外します。'};$('#topic-model-help').textContent=descriptions[method]||'';$('#transformer-help').textContent=sbert?'Sentence-BERT（SBERT）は、Sentence Transformersライブラリで利用する文章埋め込みモデル群です。初回は選択モデルの取得が必要で、その後の文章分析はローカルで行います。':counts?(method==='lda'?'SBERTは使用しません。LDAは単語カウントからテーマを推定します。':'SBERTは使用しません。NMFはTF-IDFからテーマを分解します。'):'TF-IDFは追加モデルのダウンロード不要で、手元の論文だけを使って分析できます。';const preset=state.status?.sbert_models?.find(m=>m.id===$('#sbert-model').value);$('#sbert-model-help').textContent=preset?`${preset.language||''}${preset.language?' · ':''}${preset.model_id||preset.label||preset.id}`:$('#sbert-model').value==='mpnet'?'MPNet：英語論文向け。sentence-transformers/all-mpnet-base-v2':'Multilingual MiniLM：日本語を含む多言語向け。既存の意味分析モデルです。';const missing=[];if(sbert&&!sbertAvailable())missing.push('SBERTを利用するにはSentence Transformersの追加環境が必要です。');if(!selectedTopicAvailable(method))missing.push(`${topicModelName(method)}の追加環境が見つかりません。サーバーで依存ライブラリを追加してください。`);$('#model-availability-note').hidden=!missing.length;$('#model-availability-note').textContent=missing.join(' ');}
function modelConfigurationError(){const method=$('#topic-model').value;if(!selectedTopicAvailable(method))return `${topicModelName(method)}の追加環境が利用できません。`;if($('#embedding').value==='sbert'&&!sbertAvailable())return 'Sentence-BERTの追加環境が利用できません。';return '';}
function topicFor(id){return state.result?.topics.find(t=>t.id===id);}
function knownCitations(papers){return papers.filter(p=>p.citations!=null);}
function topicCitationTotal(id){const topic=topicFor(id);if(Object.hasOwn(topic||{},'citation_total'))return topic.citation_total;if(state.result?.meta?.papers_truncated)return null;const papers=knownCitations(state.result.papers.filter(p=>p.topic_id===id));return papers.length?papers.reduce((sum,p)=>sum+p.citations,0):null;}
function topicCitationMean(id){const topic=topicFor(id);if(Object.hasOwn(topic||{},'citation_mean'))return topic.citation_mean==null?'—':Number(topic.citation_mean).toFixed(1);if(state.result?.meta?.papers_truncated)return '—';const papers=knownCitations(state.result.papers.filter(p=>p.topic_id===id));return papers.length?(papers.reduce((sum,p)=>sum+p.citations,0)/papers.length).toFixed(1):'—';}
function activeTopic(){return topicFor(state.topic)||classifiedTopics()[0]||state.result?.topics[0];}
function topicColor(id){return topicPaint(topicFor(id));}
function empty(title,description,action=""){return `<div class="empty-state">${icon("orbit")}<h3>${e(title)}</h3><p>${e(description)}</p>${action}</div>`;}
function panelHeader(title,subtitle,actions=""){return `<div class="panel-header"><div><div class="panel-heading"><h2>${e(title)}</h2></div>${subtitle?`<div class="panel-eyebrow">${e(subtitle)}</div>`:""}</div>${actions?`<div class="panel-actions">${actions}</div>`:""}</div>`;}
function linkView(view,text){return `<button class="text-link" data-view="${e(view)}">${e(text)} ${icon("arrow")}</button>`;}
function message(text,error=false){const el=$("#toast");el.textContent=text;el.classList.toggle("error",error);el.hidden=false;clearTimeout(message.timer);message.timer=setTimeout(()=>el.hidden=true,5500);}
async function api(url,options={}){let response;try{response=await (window.AtlasConnections?.fetch||fetch)(url,options);}catch(error){if(error.name==="AbortError")throw error;throw new Error("ローカルサーバーに接続できません。start.batでアプリを起動し、この画面を再読み込みしてください。");}if(!response.ok){let detail;try{detail=(await response.json()).detail;}catch{detail=`リクエストに失敗しました (${response.status})`;}throw new Error(typeof detail==="string"?detail:JSON.stringify(detail));}return response.json();}
const post=(url,data)=>api(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});
function closeDialogs(){ $$("dialog[open]").forEach(d=>d.close()); }
function openDialog(id){closeDialogs();$(id).showModal();}
function showLoading(stage="データを準備しています"){ $("#content").innerHTML=`<div class="loading-state"><div class="loader-orbit">${icon("orbit")}</div><div class="eyebrow">CONNECTING THE SIGNALS</div><h2>研究のつながりを、読み解く。</h2><p id="loading-stage">${e(stage)}</p><div class="loading-dots"><i></i><i></i><i></i></div></div>`; }
function showError(error){$("#content").innerHTML=empty("分析を完了できませんでした",error.message,`<button class="button button-primary" data-action="analyze">もう一度試す</button> <button class="button button-quiet" data-action="upload">データを追加</button>`);}
function applyDatasetAnalysisDefaults(dataset){const defaults=dataset?.analysis_defaults;$('#monthly-anchor').value=defaults?.anchor_month||'';if(!defaults)return;if(Number.isInteger(defaults.start_year))$('#start-year').value=defaults.start_year;if(Number.isInteger(defaults.end_year))$('#end-year').value=defaults.end_year;if([1,3,6].includes(defaults.window_months))$('#monthly-window').value=String(defaults.window_months);}
function updateDataset(){if(!state.dataset)return;$("#dataset-name").textContent=state.dataset.name;$("#demo-badge").hidden=!state.dataset.is_demo;}
function resetFilters(){state.query="";state.paperAuthor=null;state.paperRemote=null;state.paperRequest=(state.paperRequest||0)+1;state.paperCache=new Map();state.paperDetailRequest=(state.paperDetailRequest||0)+1;state.paperTopic="all";state.paperYear="all";state.paperPage=0;state.author=null;state.keywordQuery="";state.authorQuery="";state.mapHighlight=null;state.sparseCandidate=null;}
let statusRequest=0;
async function refreshStatus(){const request=++statusRequest,status=await api("/api/status");if(request!==statusRequest)return;state.status=status;$("#llm-status").textContent=status.llm_configured?"OpenAI設定あり · 仮説生成を利用できます":"OpenAI未設定 · 数値分析を利用できます";updateModelCatalog();}
function readOptions(){return {start_year:Number($("#start-year").value),end_year:Number($("#end-year").value),n_topics:Number($("#topic-count").value),embedding:$("#embedding").value,horizon:Number($("#forecast-horizon").value),window_months:Number($("#monthly-window").value),anchor_month:$("#monthly-anchor").value||null,topic_model:$("#topic-model").value,sbert_model:$("#sbert-model").value,min_topic_size:$("#topic-model").value==='bertopic'?Number($("#min-topic-size").value):5};}
async function runAnalysis(){
 if(!state.dataset){return loadDemo();}clearRestoreLink();++state.selectionVersion;const run=++state.run;resetFieldReport();resetAuthorNetwork();state.result=null;window.dispatchEvent(new CustomEvent('atlas:result',{detail:null}));state.insight=null;state.insightBusy=false;state.mapZoom=1;$("#notice").hidden=true;$("#source-notice").hidden=true;$("#analysis-time").textContent="分析中";showLoading("テキスト表現・技術クラスタ・時系列を計算しています");
 const options=readOptions();$("#period-label").textContent=`${options.start_year} — ${options.end_year}`;
 try{const job=await post("/api/analyze",{dataset_id:state.dataset.id,...options});while(run===state.run){const update=await api(`/api/jobs/${encodeURIComponent(job.job_id)}`);if(run!==state.run)return;if(update.status==="failed")throw new Error(update.error||"分析処理が失敗しました。");if(update.status==="completed"){const completed=await api(`/api/results/${encodeURIComponent(update.result_id)}?view=summary`);if(run!==state.run)return;state.result=completed;window.dispatchEvent(new CustomEvent('atlas:result',{detail:completed}));state.topic=classifiedTopics()[0]?.id||state.result.topics[0]?.id;resetFilters();$("#analysis-time").textContent=`${new Date().toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"})} 更新`;$("#embedding-label").textContent=analysisMethodLabel(state.result.meta);$("#embedding-label").title=`テーマ抽出：${topicModelName(state.result.meta.topic_model)} / マップ：${mapRepresentationLabel(state.result.meta)}`;$("#period-label").textContent=`${state.result.meta.start_year} — ${state.result.meta.end_year}`;$("#demo-badge").hidden=!state.result.meta.is_demo;render();renderWarnings();renderSourceNotice();loadInsights(false);return;}if($("#loading-stage"))$("#loading-stage").textContent=update.stage||"分析を進めています";await new Promise(resolve=>setTimeout(resolve,900));}}
 catch(error){if(run===state.run){$("#analysis-time").textContent="分析エラー";showError(error);}}
}
async function loadDemo(){const selection=++state.selectionVersion;try{closeDialogs();showLoading("合成デモデータを読み込んでいます");const demo=(await post("/api/demo",{})).dataset;if(selection!==state.selectionVersion)return;await refreshStatus();if(selection!==state.selectionVersion)return;state.dataset=demo;applyDatasetAnalysisDefaults(demo);updateDataset();await runAnalysis();}catch(error){if(selection===state.selectionVersion)showError(error);}}
function renderWarnings(){const warnings=state.result?.meta?.warnings||[];const el=$("#notice");if(!warnings.length){el.hidden=true;return;}el.hidden=false;const publicData=currentSourceReports().length>0,mixed=(state.result.meta.citation_sources||[]).length>1;const text=publicData?`${mixed?"引用の計数元が混在しています。":"抄録・著者・引用の取得条件："} <button class="text-link" data-action="methodology">${warnings.length}件の注意事項を確認</button>`:`${e(warnings[0])}${warnings.length>1?` <button class="text-link" data-action="methodology">ほか${warnings.length-1}件の注意事項を見る</button>`:""}`;el.innerHTML=`${icon("info")}<span>${text}</span><button data-dismiss-notice aria-label="注意事項を閉じる">×</button>`;}
const viewLabels={foresight:["EVIDENCE-GROUNDED FORESIGHT","有望領域を、根拠から探索する。","成長の観測と実用化に関する証拠を分け、追加探索で候補を検証する。"],overview:["OVERVIEW","研究の現在地と、その先へ。","論文に散らばるシグナルから、次の技術の可能性を見つける。"],technology:["TECHNOLOGY LANDSCAPE","技術の距離から、つながりを探る。","選択した文章表現やテーマ分布で研究領域を配置。点を選ぶと、根拠となる論文を確認できます。"],keywords:["KEYWORD MOMENTUM","言葉の変化に、兆しを見つける。","年ごとの出現頻度と成長率から、研究コミュニティの関心を読み解く。"],authors:["COLLABORATION NETWORK","研究をつなぐ、人を知る。","共著関係から研究コミュニティと、その中心にいる著者を探索する。"],citations:["CITATION INTELLIGENCE","研究の影響を、時間で捉える。","年別の引用イベントと、出版年ごとの累積被引用数を分けて読み解く。"],forecasts:["FUTURE HORIZONS","次の可能性を、根拠から描く。","出版数の時系列から探索的なシナリオを推定し、検証結果とともに比較する。"],papers:["EVIDENCE LIBRARY","すべての分析を、論文へつなぐ。","原典の抄録・著者・キーワードを確認し、シグナルの根拠をたどる。"]};
function render(){const [eyebrow,title,description]=viewLabels[state.view]||viewLabels.overview;$("#view-eyebrow").textContent=eyebrow;$("#page-title").textContent=title;$("#page-description").textContent=description;$$('#navigation [data-view]').forEach(b=>{b.classList.toggle("active",b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute("aria-current","page");else b.removeAttribute("aria-current");});if(!state.result)return;const views={overview:renderOverview,technology:renderTechnology,keywords:renderKeywords,authors:renderAuthors,citations:renderCitations,forecasts:renderForecasts,papers:renderPapers,foresight:()=>'<div id="foresight-root"></div>'};$("#content").innerHTML=largeCorpusNotice()+views[state.view]();if(state.view==='papers'&&state.result.meta?.papers_truncated)loadPaperPage();if(state.view==='authors')ensureAuthorNetwork();if(state.view==='foresight')window.AtlasForesight?.mount($('#foresight-root'),state.result);}
function setView(view){if(!viewLabels[view])return;state.view=view;state.mapZoom=1;$("#tooltip").hidden=true;render();renderSourceNotice();window.scrollTo({top:0,behavior:"instant"});}
function kpi(label,value,unit,sub,iconName,featured=false){return `<div class="kpi ${featured?"kpi-featured":""}"><div class="kpi-top"><span>${e(label)}</span>${icon(iconName)}</div><div class="kpi-value">${num(value)}<small>${e(unit)}</small></div><div class="kpi-sub">${sub}</div></div>`;}
function renderOverview(){const r=state.result,s=r.summary;const top=classifiedTopics().sort((a,b)=>b.score-a.score).slice(0,5);return `<div class="kpi-grid">${kpi("分析対象の論文",s.papers,"PAPERS",`<span class="${s.growth_pct<0?'negative':'positive'}">${pct(s.growth_pct)}</span><span>直近年の前年比</span>`,"file")}${kpi("研究者ネットワーク",s.authors,"AUTHORS","分析対象論文のユニーク著者","network")}${kpi("累積被引用数",(r.meta.papers_truncated?r.meta.citation_snapshot_coverage>0:knownCitations(r.papers).length)?s.citations:null,"CITATIONS","取得時点 / 取得済み値の合計","quote")}${kpi("分類されたテーマ",classifiedTopics().length,"TOPICS",`${num(s.keywords)} キーワード${unclassifiedPaperCount()?` · 未分類 ${num(unclassifiedPaperCount())}論文`:""}`,"orbit")}${kpi("新興技術のシグナル",r.meta.annual_comparison_available===false?null:s.emerging_topics,"SIGNALS",r.meta.annual_comparison_available===false?"年次比較の情報が不足":"出版動向から注目候補を検出","sparkles",true)}</div><div class="overview-grid"><section class="panel">${panelHeader("技術ランドスケープ","TECHNOLOGY LANDSCAPE",linkView("technology","マップを探索"))}${semanticMap(false)}${mapLegend()}<div class="map-caption">点 = 論文 · 大きさ = 累積被引用数 · 色 = 技術トピック · 線 = 論文表現の類似度（引用関係ではありません）</div></section><section class="panel">${panelHeader("いま、注目のシグナル","SIGNALS TO WATCH",`<span class="source-pill">TOP ${top.length}</span>`)}<p class="signal-intro">出版成長・最近の活動・引用影響を総合</p><div class="signal-list">${top.map((t,i)=>`<button class="signal-row" data-topic="${e(t.id)}"><span class="signal-rank">${String(i+1).padStart(2,"0")}</span><span><strong class="signal-name">${e(t.label)}</strong><span class="signal-tags">${badge(t)}<span>${num(t.count)} 論文</span></span></span><span class="signal-change">${num(t.score)}<small>シグナルスコア</small></span></button>`).join("")||'<div class="topic-empty">分類されたテーマがありません。未分類の論文は技術マップ・論文一覧で確認できます。</div>'}</div><div class="signal-bottom"><span><i class="status-dot"></i>探索の優先順位を示す参考スコア</span>${linkView("forecasts","将来予測")}</div></section></div><div class="overview-bottom"><section class="panel">${panelHeader("研究活動の推移","PUBLICATION ACTIVITY",`<span class="source-pill">${r.meta.start_year} — ${r.meta.end_year}</span>`)}<div class="chart-legend"><span><i class="line-key"></i>${unclassifiedPaperCount()?'分類済み論文数':'出版論文数'}</span>${classifiedTopics().some(t=>t.forecast?.length)?'<span><i class="line-key dashed"></i>予測シナリオ</span>':''}</div><div class="chart-wrap">${overviewChart()}</div><div class="panel-note">${unclassifiedPaperCount()?`未分類${num(unclassifiedPaperCount())}論文は、この時系列と予測から除外しています。`:""}${isSampled()?'年・月ごとの取得枠に制約された取得集合の外挿です。検索結果全体の成長は示しません。':'予測は取得した論文数の推移を外挿した探索的シナリオです。'}技術の実用化・成功を表すものではありません。</div></section><section class="panel insight-panel" id="overview-insights">${insightPreview()}</section></div>`;}
function semanticMap(large){return window.AtlasLandscape.view({large,result:state.result,view:state.view,topic:state.topic,get mapZoom(){return state.mapZoom;},mapHighlight:state.mapHighlight,api,e,num,icon,topicColor,topicPaint,mapLabels,isUnclassified,empty,representation:mapRepresentationLabel(state.result.meta)});}
function largeCorpusNotice(){const meta=state.result?.meta||{};if(!meta.papers_truncated)return '';return `<div class="corpus-size-note">${icon('database')}<span>統計・年次推移は分析対象の${num(meta.papers_total??state.result.summary?.papers)}論文を集計しています。マップは表示用の標本です。論文一覧の検索は全件を対象とし、抄録は必要な論文だけ読み込みます。</span></div>`;}
function paperRequestKey(){return JSON.stringify([state.result?.id,state.query,state.paperTopic,state.paperYear,state.paperSort,state.paperPage,state.paperAuthor||'']);}
function paperPageURL(){const params=new URLSearchParams({offset:String(Math.max(0,state.paperPage)*20),limit:'20',sort:state.paperSort||'citations'});if(state.query.trim())params.set('query',state.query.trim());if(state.paperTopic!=='all')params.set('topic_id',state.paperTopic);if(state.paperYear!=='all')params.set('year',state.paperYear);if(state.paperAuthor)params.set('author_id',state.paperAuthor);return `/api/results/${encodeURIComponent(state.result.id)}/papers?${params}`;}
function refreshPaperTable(delay=0){clearTimeout(refreshPaperTable.timer);state.paperRequest=(state.paperRequest||0)+1;if(!state.result)return;if(!state.result.meta?.papers_truncated){$('#papers-table').innerHTML=paperTable();return;}state.paperRemote=null;$('#papers-table').innerHTML=paperTable();if(delay)refreshPaperTable.timer=setTimeout(()=>loadPaperPage(),delay);else loadPaperPage();}
async function loadPaperPage(){if(!state.result?.meta?.papers_truncated||state.view!=='papers')return;const key=paperRequestKey(),token=state.paperRequest=(state.paperRequest||0)+1,current=()=>state.view==='papers'&&state.result?.meta?.papers_truncated&&token===state.paperRequest&&key===paperRequestKey();if(state.paperRemote?.key===key&&!state.paperRemote.error)return;try{const data=await api(paperPageURL());if(!current())return;state.paperRemote={...data,key,items:Array.isArray(data.items)?data.items:[]};}catch(error){if(!current())return;state.paperRemote={key,items:[],total:0,error:error.message};}if(current()&&$('#papers-table'))$('#papers-table').innerHTML=paperTable();}
async function getPaper(id,resultId=state.result?.id){if(!resultId)return null;const key=`${resultId}:${id}`;if(state.paperCache?.has(key))return state.paperCache.get(key);const local=state.result?.papers.find(p=>p.id===id);if(!state.result?.meta?.papers_truncated&&local)return local;const paper=await api(`/api/results/${encodeURIComponent(resultId)}/papers/${encodeURIComponent(id)}`);if(state.result?.id!==resultId)return null;if(!state.paperCache)state.paperCache=new Map();if(state.paperCache.size>=200)state.paperCache.delete(state.paperCache.keys().next().value);state.paperCache.set(key,paper);return paper;}
function mapLabels(groups,width,height){
 const occupied=[{x:10,y:5,w:170,h:38},{x:width-120,y:5,w:112,h:42},{x:width-280,y:height-44,w:272,h:40}],labels=[];
 const overlap=(a,b)=>Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x))*Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));
 [...groups].sort((a,b)=>b.count-a.count).forEach(t=>{const title=t.label.length>30?t.label.slice(0,28)+'…':t.label;const textWidth=[...title].reduce((sum,c)=>sum+(c.charCodeAt(0)>255?10:5.8),0);const w=Math.min(230,textWidth+20),h=24;let best=null;
  [37,66,102,145].forEach(distance=>[-Math.PI/2,Math.PI/2,0,Math.PI,-Math.PI/4,-3*Math.PI/4,Math.PI/4,3*Math.PI/4].forEach(angle=>{const x=clamp(t.cx+Math.cos(angle)*distance-w/2,12,width-w-12),y=clamp(t.cy+Math.sin(angle)*distance-h/2,14,height-h-14);const box={x,y,w,h};const score=occupied.reduce((sum,other)=>sum+overlap({...box,x:x-5,y:y-4,w:w+10,h:h+8},other)*100,0)+Math.hypot(x+w/2-t.cx,y+h/2-t.cy);if(!best||score<best.score)best={...box,score};}));
  occupied.push(best);const cx=best.x+best.w/2,cy=best.y+best.h/2;labels.push(`<line x1="${t.cx}" y1="${t.cy}" x2="${cx}" y2="${cy}" stroke="${topicPaint(t)}" opacity=".32" stroke-width=".7" stroke-dasharray="2 4"/><g class="map-topic-label" data-topic="${e(t.id)}" tabindex="0" role="button" aria-label="${e(t.label)} の総合分析を開く"><rect x="${best.x}" y="${best.y}" width="${best.w}" height="${best.h}" rx="4" fill="#101c2b" fill-opacity=".88" stroke="${topicPaint(t)}" stroke-opacity=".25"/><text x="${cx}" y="${cy+3.8}" font-size="10.5" font-weight="500" text-anchor="middle" fill="${topicPaint(t)}">${e(title)}</text></g>`);
 });return labels.join('');
}
function mapLegend(){return `<div class="map-legend">${state.result.topics.map(t=>`<button class="legend-item" data-topic="${e(t.id)}" style="--topic-color:${topicPaint(t)}" title="${e(t.label)}"><i class="legend-dot"></i><span>${e(t.label)}</span></button>`).join("")}</div>`;}
function makeLineChart(series,years,{height=225,forecastStart=null,unit="論文数",band=null,bar=false}={}){
 const width=720,left=43,right=19,top=20,bottom=35,plotW=width-left-right,plotH=height-top-bottom;const values=series.flatMap(s=>s.values.map(p=>p.value)).filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number);if(band)values.push(...band.map(p=>Number(p.upper)||0));const max=Math.max(1,...values)*1.15;const tick=niceTick(max/4),yMax=tick*4;const x=year=>left+(years.length===1?plotW/2:(years.indexOf(Number(year))/(years.length-1))*plotW);const y=v=>top+plotH-(Number(v)/yMax)*plotH;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${e(unit)}の年次推移 ${e(years.join('、'))}"><text x="${left}" y="11" class="chart-axis" font-size="9">${e(unit)}</text>`;for(let i=0;i<=4;i++){const value=yMax*i/4,yy=y(value);svg+=`<line class="chart-grid" x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}"/><text class="chart-axis" x="${left-10}" y="${yy+3}" text-anchor="end">${num(value)}</text>`;}years.forEach((year,i)=>{if(years.length>12&&i%2&&i!==years.length-1)return;svg+=`<text class="chart-axis" x="${x(year)}" y="${height-10}" text-anchor="middle">${year}</text>`;});
 if(forecastStart&&years.includes(forecastStart)){const xx=x(forecastStart);svg+=`<rect x="${xx}" y="${top}" width="${width-right-xx}" height="${plotH}" fill="#77a8fc" opacity=".022"/><line x1="${xx}" y1="${top}" x2="${xx}" y2="${top+plotH}" stroke="#5a7798" stroke-dasharray="3 5" opacity=".6"/><text class="chart-axis" x="${xx+9}" y="${top+10}" fill="#8aabdb" font-size="8">FORECAST</text>`;}
 if(band?.length){const available=band.filter(p=>years.includes(Number(p.year))&&p.lower!=null&&p.upper!=null);if(available.length>1){const poly=[...available.map(p=>`${x(p.year)},${y(p.upper)}`),...available.slice().reverse().map(p=>`${x(p.year)},${y(p.lower)}`)].join(' ');svg+=`<polygon points="${poly}" fill="#77a8fc" opacity=".12"/>`;}}
 series.forEach((s,si)=>{const c=color(s.color),points=s.values.filter(p=>years.includes(Number(p.year)));const available=points.filter(p=>p.value!=null&&Number.isFinite(Number(p.value)));if(!available.length)return;let segments=[],current=[];points.forEach(p=>{if(p.value==null){if(current.length)segments.push(current);current=[];}else current.push(p);});if(current.length)segments.push(current);if(s.area){segments.forEach(part=>{svg+=`<polygon points="${x(part[0].year)},${top+plotH} ${part.map(p=>`${x(p.year)},${y(p.value)}`).join(' ')} ${x(part.at(-1).year)},${top+plotH}" fill="${c}" opacity=".055"/>`;});}if(bar){const bw=Math.min(53,plotW/Math.max(years.length,1)*.45);available.forEach(p=>{svg+=`<rect x="${x(p.year)-bw/2}" y="${y(p.value)}" width="${bw}" height="${Math.max(1,top+plotH-y(p.value))}" rx="3" fill="${c}" opacity=".65" data-tooltip="${p.year}年 · ${num(p.value)} ${e(unit)}" data-tooltip-sub="${e(p.tooltip||s.label)}"/>`;});}else{segments.forEach(part=>{svg+=`<polyline points="${part.map(p=>`${x(p.year)},${y(p.value)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="2.15" stroke-linecap="round" stroke-linejoin="round" ${s.dashed?'stroke-dasharray="5 5"':''}/>`;});available.forEach(p=>{svg+=`<circle class="chart-point" cx="${x(p.year)}" cy="${y(p.value)}" r="3.4" fill="${s.dashed?'#101b29':c}" stroke="${c}" stroke-width="1.7" data-tooltip="${p.year}年 · ${num(p.value)} ${e(unit)}" data-tooltip-sub="${e(p.tooltip||s.label)}"><title>${p.year}: ${num(p.value)} ${e(s.label)}</title></circle>`;});}points.filter(p=>p.value==null).forEach(p=>{svg+=`<text class="chart-axis" x="${x(p.year)}" y="${top+plotH-9}" text-anchor="middle" font-size="8">未取得</text>`;});});return svg+"</svg>";
}
function niceTick(value){if(value<=1)return 1;const power=Math.pow(10,Math.floor(Math.log10(value)));const scaled=value/power;return (scaled<=1?1:scaled<=2?2:scaled<=5?5:10)*power;}
function overviewChart(){const r=state.result,classified=classifiedTopics(),hasOutliers=unclassifiedPaperCount()>0;if(!classified.length)return '<div class="topic-empty">分類されたテーマがないため、出版数の予測シナリオは表示していません。</div>';const actual=r.timeline.map(row=>({year:row.year,value:hasOutliers?classified.reduce((sum,t)=>sum+(t.series.find(point=>point.year===row.year)?.count||0),0):row.papers}));const futureYears=[...new Set(classified.flatMap(t=>(t.forecast||[]).map(f=>f.year)))].sort((a,b)=>a-b),forecast=futureYears.map(year=>({year,value:classified.reduce((sum,t)=>sum+((t.forecast||[]).find(f=>f.year===year)?.value||0),0)})),allYears=[...r.meta.years,...futureYears];const series=[{label:hasOutliers?'分類済みの出版論文数':'出版論文数',color:'#58e0c5',area:true,values:actual}];if(forecast.length)series.push({label:'予測シナリオ · 分類済みテーマ別予測の合計',color:'#77a8fc',dashed:true,values:[actual.at(-1),...forecast].filter(Boolean)});return makeLineChart(series,allYears,{forecastStart:forecast.length?r.meta.end_year:null,unit:hasOutliers?'分類済み論文数':'論文数'});}
function sparkline(values,c){const nums=values.map(v=>Number(v)||0),max=Math.max(1,...nums);return `<svg viewBox="0 0 200 42" aria-hidden="true"><path d="M0 38H200" stroke="#283b4d" stroke-dasharray="3 4"/><polyline fill="none" stroke="${color(c)}" stroke-width="1.7" points="${nums.map((v,i)=>`${i*200/Math.max(1,nums.length-1)},${35-v/max*28}`).join(' ')}"/></svg>`;}
function insightPreview(){const insight=state.insight;return `<div class="panel-header"><div class="panel-heading"><span class="insight-header-icon">${icon("sparkles")}</span><div><h2>シグナルの読み解き</h2><div class="panel-eyebrow">${insight?.mode==='llm'?'LLM-GROUNDED HYPOTHESES':'EVIDENCE-BASED INSIGHTS'}</div></div></div><span class="source-pill">${insight?.mode==='llm'?'LLM':'LOCAL'}</span></div><div class="insight-body">${state.insightBusy?'<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>':insight?`<h3 class="insight-headline">${e(insight.headline)}</h3><ul class="insight-list">${insight.findings.slice(0,2).map(f=>`<li>${e(f)}</li>`).join('')}</ul>`:'<p class="muted">計測した研究動向から、根拠のあるシグナルを整理します。</p>'}</div><div class="insight-footer"><span>数値分析から生成 · すべての洞察に根拠を</span><button data-action="insights">洞察を開く ${icon("arrow")}</button></div><div class="insight-disclosure">予測の解釈と仮説は分けて表示。LLMへの外部送信は明示的な操作時のみ。</div>`;}
function technologyTabs(){return `<div class="technology-tabs" role="tablist" aria-label="技術の探索方法">${[['map','orbit','技術マップ'],['monthly','trend','月次の兆し'],['sparse','target','少ない組み合わせ']].map(([id,ic,label])=>`<button role="tab" aria-selected="${state.technologyTab===id}" class="${state.technologyTab===id?'active':''}" data-technology-tab="${id}">${icon(ic)}${label}</button>`).join('')}<span>EXPLORE THE NEXT QUESTION</span></div>`;}
function renderTechnology(){const tabs=technologyTabs();if(state.technologyTab==='monthly')return tabs+renderMonthly();if(state.technologyTab==='sparse')return tabs+renderSparse();const t=activeTopic(),monthly=state.result.frontiers?.monthly;return `${tabs}<div class="view-grid"><section class="panel">${panelHeader("技術ランドスケープ","EXPLORABLE SEMANTIC MAP",`<button class="button button-quiet button-small" data-action="map-recent" ${monthly?.available?'':'disabled'} title="月次データのある直近期間の論文を強調">${icon('calendar')}直近${monthly?.window_months||3}か月</button><span class="source-pill">${num(state.result.map.nodes.length)} PAPERS</span>`)}${highlightBanner()}${semanticMap(true)}${mapLegend()}<div class="panel-note">分野タイトルを選ぶと総合分析、点を選ぶと論文を表示します。2次元投影の空白や密度だけでは、研究が少ない領域を判断できません。「少ない組み合わせ」で実際の語句共起を比較できます。${state.result.map.truncated?'表示論文を絞り込んでいます。':''}</div></section>${topicDetail(t)}</div><div class="section-title"><h2>研究領域を探索</h2><span>${classifiedTopics().length} TOPICS${unclassifiedPaperCount()?` / 未分類 ${num(unclassifiedPaperCount())} 論文`:""}</span></div><div class="topic-cards">${state.result.topics.map(topic=>topicCard(topic)).join('')}</div>`;}
function monthText(value){const match=/^(\d{4})-(\d{2})/.exec(String(value||''));return match?`${match[1]}年${Number(match[2])}月`:'未設定';}
function monthRange(values){return Array.isArray(values)&&values.length?`${monthText(values[0])} — ${monthText(values.at(-1))}`:'期間未設定';}
function monthlyBadge(topic){if(isUnclassified(topicFor(topic.topic_id)))return '<span class="badge badge-unclassified">未分類</span>';const labels={rising:'増加候補',new:'新規観測',stable:'横ばい',declining:'減少',insufficient:'判定不足'};return `<span class="badge badge-${e(topic.status)}">${e(labels[topic.status]||'未判定')}</span>`;}
function monthlyGrowth(topic){if(isUnclassified(topicFor(topic.topic_id)))return '未分類';return topic.status==='insufficient'?'未判定':topic.growth_pct==null?(topic.baseline_count===0&&topic.recent_count>0?'比較期0件': '—'):pct(topic.growth_pct);}
function pointChange(value){return value==null?'—':`${Number(value)>0?'+':''}${Number(value).toFixed(1)} pt`;}
function frontierStat(label,value,note,accent=false){return `<div class="frontier-stat ${accent?'accent':''}"><span>${e(label)}</span><strong>${value}</strong><p>${e(note)}</p></div>`;}
function renderMonthly(){const m=state.result.frontiers?.monthly;if(!m)return `<section class="panel">${empty('月次分析を準備する','現在の分析結果には月次の指標がありません。分析を再実行すると利用できます。','<button class="button button-primary" data-action="analyze">月次も含めて再分析</button>')}</section>`;const topics=Array.isArray(m.topics)?m.topics:[],months=Array.isArray(m.months)?m.months:[],rising=topics.filter(t=>!isUnclassified(topicFor(t.topic_id))&&['rising','new'].includes(t.status));const warnings=Array.isArray(m.warnings)?m.warnings:[];let html=`<div class="frontier-summary">${frontierStat('基準となる完了月',e(monthText(m.anchor_month)),`最新完了月：${monthText(m.latest_complete_month)}`)}${frontierStat('月まで特定できた論文',`${num(m.dated_papers)} <small>件</small>`,`月情報なし：${num(m.undated_papers)}件`)}${frontierStat('出版月の収録率',percent(m.date_coverage),'月不明の論文を0件として扱いません')}${frontierStat('増加・新規観測の候補',m.available?`${rising.length} <small>領域</small>`:'未判定',`直近${m.window_months}か月と直前${m.window_months}か月`,true)}</div>`;if(isSampled())html+=`<div class="data-callout warning">${icon('warning')}<div><strong>取得標本の中での月次変化です。</strong><p>取得枠・並び順に制約された論文集合です。増加率や新規観測は、検索結果全体の研究成長を示しません。</p></div></div>`;if(m.stale)html+=`<div class="data-callout warning">${icon('calendar')}<div><strong>基準月は現在の最新完了月より前です。</strong><p>${monthText(m.anchor_month)}までの記録を比較しています。現在の動向を確認するには、最近の月を含むデータを追加してください。</p></div></div>`;if(!m.available)return html+`<section class="panel monthly-empty">${empty('月次の増加は、まだ判定できません。',m.reason_label||'比較に必要な出版月の情報・対象期間が不足しています。年単位の件数から月次の増加は推定しません。',`<button class="button button-primary" data-action="recent-search">${icon('search')}公開論文の最近12か月を取得</button> <button class="button button-quiet" data-action="csv-upload">日付を含むCSVを再取込</button>`)}<div class="monthly-quality"><strong>月次分析に必要なデータ</strong>Publication date / Cover Date / Monthなどで出版月を特定できること、および直近と比較期の両方を取得していることが必要です。過去に年だけで取り込んだデータは、日付を含めて再取得してください。${warnings.map(w=>`<p>${e(w)}</p>`).join('')}</div></section>`;const max=Math.max(1,...topics.flatMap(t=>(t.series||[]).map(p=>p.count)));const recent=new Set(m.recent_months||[]),baseline=new Set(m.baseline_months||[]);html+=`<div class="monthly-grid"><section class="panel">${panelHeader('研究領域の月次推移','MONTHLY TOPIC ACTIVITY',`<button class="text-link" data-action="settings">比較期間を変更 ${icon('sliders')}</button>`)}<div class="monthly-key"><span><i></i>直近：${e(monthRange(m.recent_months))}</span><span><i class="baseline"></i>比較：${e(monthRange(m.baseline_months))}</span></div><div class="table-wrap monthly-heatmap"><table><thead><tr><th>技術トピック</th>${months.map(p=>`<th class="num ${recent.has(p.month)?'recent-month':baseline.has(p.month)?'baseline-month':''}">${e(p.month.slice(2).replace('-','/'))}</th>`).join('')}</tr></thead><tbody>${topics.map(t=>`<tr><td><button class="keyword-label" data-monthly-topic="${e(t.topic_id)}">${e(t.label)}</button></td>${months.map(p=>{const cell=t.series?.find(v=>v.month===p.month),missing=p.observed===false||cell?.observed===false,n=cell?.count??0;return `<td class="heatmap-cell"><span class="heatmap-value ${missing?'unobserved-month':''}" style="background:rgba(67,199,170,${missing ? .025 : n ?(.10+.62*n/max).toFixed(3):.025})" title="${e(monthText(p.month))} · ${missing?'取得範囲外':`${num(n)}論文`}">${missing?'未取得':num(n)}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="monthly-quality"><strong>比較窓の定義</strong>完了した月だけを比較します。取得範囲外の月は「未取得」と表示します。出現0件は、この取得集合の中での0件です。出版月が不明な論文${num(m.undated_papers)}件は除外しています。${warnings.map(w=>`<p>${e(w)}</p>`).join('')}</div></section><section class="panel">${panelHeader('最近増えている領域','RECENT MOMENTUM',`<span class="source-pill">${m.window_months} vs ${m.window_months} MONTHS</span>`)}<div class="monthly-signal-list">${topics.filter(t=>!isUnclassified(topicFor(t.topic_id))).sort((a,b)=>b.delta-a.delta).slice(0,6).map(t=>`<button class="monthly-signal" data-monthly-topic="${e(t.topic_id)}"><div class="monthly-signal-head"><strong>${e(t.label)}</strong>${monthlyBadge(t)}</div><div class="monthly-signal-values"><span><small>比較期</small>${num(t.baseline_count)} → <small>直近</small>${num(t.recent_count)}</span><span class="${t.delta<0?'negative':'positive'}">${monthlyGrowth(t)}</span></div><div class="monthly-signal-foot"><span>構成比 ${pointChange(t.share_change_pp)}</span><span>根拠を見る ↗</span></div></button>`).join('')}</div></section></div><section class="panel">${panelHeader('変化の大きさを比較','COUNTS & RELATIVE SHARE')}<div class="table-wrap monthly-topic-table"><table><thead><tr><th>研究領域</th><th class="num">比較期</th><th class="num">直近</th><th class="num">増減件数</th><th class="num">増加率</th><th class="num">構成比の変化</th><th>判定</th></tr></thead><tbody>${topics.map(t=>`<tr><td><button class="keyword-label" data-monthly-topic="${e(t.topic_id)}">${e(t.label)}</button></td><td class="num">${num(t.baseline_count)}</td><td class="num">${num(t.recent_count)}</td><td class="num">${t.delta>0?'+':''}${num(t.delta)}</td><td class="num">${monthlyGrowth(t)}</td><td class="num">${pointChange(t.share_change_pp)}</td><td>${monthlyBadge(t)}</td></tr>`).join('')}</tbody></table></div><div class="frontier-explainer">比較期が0件の場合、無限大の成長率は表示しません。比較期0件から直近3件以上になった領域を、この取得集合の「新規観測候補」として示します。世界で初めての研究という意味ではありません。少数の論文による変動や、分野ごとの刊行の遅れにも注意してください。</div></section>`;return html;}
function sparseCandidate(){const rows=state.result.frontiers?.sparse?.candidates||[];return rows.find(c=>c.id===state.sparseCandidate)||rows[0];}
function sparseRatio(candidate){return candidate.ratio==null?'—':`${(Number(candidate.ratio)*100).toFixed(1)}%`;}
function renderSparse(){const sparse=state.result.frontiers?.sparse;if(!sparse)return `<section class="panel">${empty('語句の組み合わせを調べる','現在の分析結果には組み合わせの指標がありません。分析を再実行してください。','<button class="button button-primary" data-action="analyze">再分析</button>')}</section>`;const rows=sparse.candidates||[],selected=sparseCandidate();return `<div class="data-callout">${icon('info')}<div><strong>「少ない組み合わせ」は、次の問いを探すための候補です。</strong><p>各語の出現数から独立仮定の参考件数を求め、実際の共起論文数と比較します。マップの空白座標や点の密度は判定に使いません。研究未開拓や将来性を断定するものではありません。</p></div></div>${isSampled()?`<div class="data-callout warning">${icon('warning')}<div><strong>取得標本内の語句の組み合わせです。</strong><p>対象外の論文に同じ組み合わせがある可能性があります。未取得領域や他の検索語でも確かめてください。</p></div></div>`:''}${!rows.length?`<section class="panel">${empty('表示条件に合う組み合わせがありません。','対象データの語句数・件数・共起条件により、候補が得られない場合があります。少なさを作るためにマップの空白を候補にはしていません。')}</section>`:`<div class="sparse-grid"><section class="panel">${panelHeader('少ない組み合わせ候補','UNDERREPRESENTED COMBINATIONS',`<span class="source-pill">${rows.length} CANDIDATES</span>`)}${rows.map((c,i)=>`<button class="sparse-card ${selected?.id===c.id?'selected':''}" data-sparse-candidate="${e(c.id)}"><span class="sparse-rank">${String(i+1).padStart(2,'0')}</span><span><span class="sparse-pair"><strong>${e(c.term_a)}</strong><span>×</span><strong>${e(c.term_b)}</strong></span><span class="sparse-pair-note">Aを含む ${num(c.count_a)}件 · Bを含む ${num(c.count_b)}件<br>独立仮定の参考件数 ${Number(c.expected).toFixed(1)}件</span><span class="sparse-meter"><i style="width:${clamp(Number(c.ratio)*100,0,100)}%"></i></span></span><span class="sparse-observed">${num(c.observed)}<small>実際の共起論文</small><small>参考件数の ${sparseRatio(c)}</small></span></button>`).join('')}</section>${sparseDetail(selected)}</div>`}<section class="panel" style="margin-top:19px">${panelHeader('この指標が測っていること','METHOD & LIMITS')}<div class="frontier-explainer" style="border-top:0">${e(sparse.method||'対象文献全体の語句出現・共起を数え、独立仮定の参考値と比較します。')}${(sparse.warnings||[]).map(w=>`<p style="margin-top:9px">${e(w)}</p>`).join('')}</div></section>`;}
function sparseDetail(c){if(!c)return '';return `<aside class="panel sparse-detail"><div class="eyebrow">SELECTED COMBINATION</div><h3>${e(c.term_a)}<span>×</span>${e(c.term_b)}</h3><div class="sparse-terms"><div><small>A · ${e(c.term_a)}</small><strong>${num(c.count_a)}<small>論文</small></strong></div><div><small>B · ${e(c.term_b)}</small><strong>${num(c.count_b)}<small>論文</small></strong></div></div><div class="sparse-comparison"><div><span>実際の共起</span><strong class="positive">${num(c.observed)}</strong></div><div><span>独立仮定の参考件数</span><strong>${Number(c.expected).toFixed(1)}</strong></div></div><p class="field-help">2つの語が独立に使われるという仮定に対し、実際の共起は参考件数の${sparseRatio(c)}です。専門領域の違い、同義語、抽出・検索範囲の偏りでも少なく見えます。</p><button class="button button-primary" data-sparse-evidence="${e(c.id)}">根拠の論文を比較 ${icon('arrow')}</button><button class="button button-quiet" data-sparse-map="${e(c.id)}">根拠論文をマップで強調 ${icon('orbit')}</button><p class="field-help">実在する根拠論文の点だけを強調します。新しい「空白領域」の座標は作りません。</p></aside>`;}
function highlightBanner(){const h=state.mapHighlight;if(!h)return '';const ids=new Set(h.ids),visible=state.result.map.nodes.filter(n=>ids.has(n.id)).length;return `<div class="frontier-highlight">${icon('target')}<div><strong>${e(h.label)}</strong><p>対象${num(h.ids.length)}論文のうち、このマップに表示中の${num(visible)}点を強調しています。${e(h.note||'')}</p></div><button data-action="clear-map-highlight">強調を解除 ×</button></div>`;}
function monthlyIDs(topic=null){const months=new Set(state.result.frontiers?.monthly?.recent_months||[]);return state.result.papers.filter(p=>(!topic||p.topic_id===topic)&&months.has(String(p.publication_date||'').slice(0,7))).map(p=>p.id);}
function highlightRecent(topic=null){const m=state.result.frontiers?.monthly;if(!m?.available)return;const ids=monthlyIDs(topic);state.mapHighlight={ids,label:`${topicFor(topic)?.label||'全研究領域'} · ${monthRange(m.recent_months)}`,note:'出版月を特定できる直近期間の論文です。'};if(topic)state.topic=topic;state.technologyTab='map';closeDialogs();setView('technology');}
function highlightSparse(id){const c=state.result.frontiers?.sparse?.candidates?.find(c=>c.id===id);if(!c)return;state.sparseCandidate=c.id;state.mapHighlight={ids:[...new Set([...(c.evidence_a||[]),...(c.evidence_b||[]),...(c.joint_evidence_ids||[])])],label:`${c.term_a} × ${c.term_b} · 根拠論文`,note:'語句の共起指標の根拠を表示しています。空白座標を推定したものではありません。'};state.technologyTab='map';closeDialogs();setView('technology');}
function showMonthlyTopic(id){const m=state.result.frontiers?.monthly,t=m?.topics?.find(t=>t.topic_id===id);if(!t)return;$('#detail-eyebrow').textContent='MONTHLY MOMENTUM EVIDENCE';$('#detail-title').textContent=t.label;$('#detail-body').innerHTML=`<div class="frontier-evidence-header">${monthlyBadge(t)}<h3>${num(t.baseline_count)} → ${num(t.recent_count)} 論文</h3></div><div class="month-range">比較期：${e(monthRange(m.baseline_months))}<br>直近：${e(monthRange(m.recent_months))}</div><div class="topic-metrics"><div><span>増加率</span><strong style="font-size:20px">${monthlyGrowth(t)}</strong></div><div><span>構成比の変化</span><strong style="font-size:20px">${pointChange(t.share_change_pp)}</strong></div></div><p class="muted">${isSampled()?'取得標本内の変化です。検索全体の成長は示しません。':'取得した論文集合の中での変化です。'}比較期が0件のときは増加率を算出せず、出現件数を確認します。</p><div class="detail-section"><h3>根拠となる論文</h3>${evidenceList(t.evidence_ids||[],12)}</div><button class="button button-primary" data-monthly-map="${e(id)}">直近の論文をマップで強調 ${icon('orbit')}</button>`;openDialog('#detail-dialog');}
function showSparseEvidence(id,part='a'){const c=state.result.frontiers?.sparse?.candidates?.find(c=>c.id===id);if(!c)return;state.sparseCandidate=id;$('#detail-eyebrow').textContent='COMBINATION EVIDENCE';$('#detail-title').textContent=`${c.term_a} × ${c.term_b}`;const groups={a:c.evidence_a||[],b:c.evidence_b||[],joint:c.joint_evidence_ids||[]};const label=part==='a'?`「${c.term_a}」を含む論文`:part==='b'?`「${c.term_b}」を含む論文`:'両方の語を含む論文';$('#detail-body').innerHTML=`<div class="sparse-comparison" style="margin-top:0"><div><span>実際の共起</span><strong class="positive">${num(c.observed)}</strong></div><div><span>独立仮定の参考件数</span><strong>${Number(c.expected).toFixed(1)}</strong></div><div><span>観測 / 参考値</span><strong>${sparseRatio(c)}</strong></div></div><p class="muted">研究未開拓の証明ではありません。語句A/Bそれぞれの文脈と、共通する論文を比較し、組み合わせが少ない理由を検討できます。</p><div class="segmented sparse-evidence-tabs"><button class="${part==='a'?'active':''}" data-sparse-part="a">語句Aの論文</button><button class="${part==='b'?'active':''}" data-sparse-part="b">語句Bの論文</button><button class="${part==='joint'?'active':''}" data-sparse-part="joint">両方を含む論文</button></div><h3 style="font-size:12px">${e(label)}</h3>${groups[part].length?evidenceList(groups[part],15):'<div class="topic-empty">表示できる共起の根拠論文はありません。未取得の研究全体に存在しないことを意味しません。</div>'}<button class="button button-quiet" data-sparse-map="${e(id)}">根拠の点をマップで強調 ${icon('orbit')}</button>`;openDialog('#detail-dialog');}
function topicCard(t){return `<button class="topic-card ${isUnclassified(t)?'unclassified-card':''} ${state.topic===t.id?'selected':''}" style="--topic-color:${topicPaint(t)}" data-topic="${e(t.id)}"><div class="topic-card-top"><i class="legend-dot" style="--topic-color:${topicPaint(t)}"></i>${badge(t)}</div><h3 class="topic-card-title">${e(t.label)}</h3><p class="topic-card-keywords">${isUnclassified(t)?'共通するテーマへ分類できなかった論文':e(t.keywords.slice(0,4).join(' / '))}</p><div class="mini-chart">${sparkline(t.series.map(s=>s.count),topicPaint(t))}</div><div class="topic-card-bottom"><span>${num(t.count)} 論文</span><strong class="${t.growth_pct<0?'negative':''}">${isUnclassified(t)?'未分類':pct(t.growth_pct)}</strong></div></button>`;}
function unclassifiedTopicDetail(t){return `<aside class="panel topic-detail unclassified-detail"><div class="eyebrow">UNCLASSIFIED PAPERS</div><h2>${e(t.label||'未分類')}</h2><span class="badge badge-unclassified">未分類</span><p>共通するテーマとしてまとまらなかった論文です。ひとつの研究領域ではなく、注目度の順位付け・成長候補・数値予測には含めません。</p><div class="topic-metrics"><div><span>未分類の論文</span><strong>${num(t.count)}</strong><small> 件</small></div><div><span>全論文に占める割合</span><strong>${percent(t.share)}</strong></div><div><span>累積被引用数</span><strong>${num(topicCitationTotal(t.id))}</strong></div></div><p class="field-help">テーマ数の目安や最小テーマサイズを調整すると分類が変わる場合があります。論文そのものは分析結果に保存されています。</p><h3>未分類の論文を確認</h3>${evidenceList(t.evidence_ids||[],4)}<button class="button button-quiet button-small" data-evidence-topic="${e(t.id)}">未分類の論文一覧 ${icon('arrow')}</button><button class="button button-quiet button-small" data-action="settings">テーマ抽出の設定 ${icon('sliders')}</button></aside>`;}
function topicDetail(t,forecast=false){if(!t)return `<div class="panel">${empty("トピックがありません","分析条件を変更してください。")}</div>`;if(isUnclassified(t))return unclassifiedTopicDetail(t);const bt=t.backtest||{};return `<aside class="panel topic-detail"><div class="eyebrow">${forecast?'SCENARIO OUTLOOK':'SELECTED TECHNOLOGY'}</div><div class="score-ring"><svg viewBox="0 0 60 60" aria-hidden="true"><circle cx="30" cy="30" r="25" fill="none" stroke="#263d4c" stroke-width="2"/><circle cx="30" cy="30" r="25" fill="none" stroke="${topicPaint(t)}" stroke-width="2.5" stroke-dasharray="${clamp(t.score,0,100)*1.57} 157"/></svg><strong>${num(t.score)}</strong></div><h2>${e(t.label)}</h2>${badge(t)}<p>${e(t.explanation)}</p><div class="topic-metrics"><div><span>出版論文数</span><strong>${num(t.count)}</strong><small> 件</small></div><div><span>平滑化成長率</span><strong class="${t.growth_pct<0?'negative':'positive'}">${pct(t.growth_pct)}</strong></div><div><span>累積被引用数</span><strong>${num(topicCitationTotal(t.id))}</strong></div><div><span>論文の構成比</span><strong>${percent(t.share)}</strong></div></div>${forecast?`<h3>過去データでの検証</h3><div class="mini-metrics"><span>モデル MAE<strong>${bt.mae==null?'—':Number(bt.mae).toFixed(1)}</strong></span><span>ベースライン MAE<strong>${bt.baseline_mae==null?'—':Number(bt.baseline_mae).toFixed(1)}</strong></span></div><p class="field-help">検証点 ${num(bt.folds)} · MAEは予測誤差の平均（論文数）。小さいほど良い値です。トピック分類は全期間で抽出しているため、完全な前向き検証ではありません。</p>`:`<h3>トピックを構成する言葉</h3><div class="tags">${t.keywords.slice(0,8).map(k=>`<span class="tag">${e(k)}</span>`).join('')}</div>`}<h3>根拠となる論文</h3>${evidenceList(t.evidence_ids,3)}<button class="button button-quiet button-small" data-evidence-topic="${e(t.id)}">この領域の論文を見る ${icon("arrow")}</button>${!forecast?`<button class="button button-quiet button-small" data-forecast-topic="${e(t.id)}">予測シナリオを見る ${icon("trend")}</button>`:''}</aside>`;}
function evidenceList(ids,limit=5){const papers=ids.slice(0,limit).map(id=>state.result.papers.find(p=>p.id===id)||state.paperCache?.get(`${state.result.id}:${id}`)||state.paperRemote?.items?.find(p=>p.id===id)||(state.result?.meta?.papers_truncated?{id,title:`論文 ${id}`,not_loaded:true}:null)).filter(Boolean);return `<div class="evidence-list">${papers.map((p,i)=>`<button class="evidence-item" data-paper="${e(p.id)}"><span>${String(i+1).padStart(2,'0')}</span><span>${e(p.title)}<small>${p.not_loaded?'原典をクリックして読み込む':`${p.year} · ${p.citations==null?'引用数未取得':`${num(p.citations)} 被引用`}`}</small></span></button>`).join('')||'<p class="field-help">参照できる論文がありません。</p>'}</div>`;}
function renderKeywords(){return `<div class="filter-bar"><div class="search-box">${icon('search')}<input id="keyword-search" type="search" value="${e(state.keywordQuery)}" placeholder="キーワードを検索" aria-label="キーワードを検索"></div><span class="subtle-label">出現数は論文単位で集計</span></div><section class="panel"><div id="keywords-table">${keywordTable()}</div></section><div class="data-callout" style="margin-top:20px">${icon('info')}<div><strong>研究用語の成長を解釈する</strong><p>色が濃いセルほど、そのキーワードを含む論文が多い年です。平滑化成長率は直近の1〜2年の平均論文数と、その前の同じ長さの期間を比較し、分母に1を加えて算出します。件数が小さい言葉ほど変化率が大きくなりやすいため、件数もあわせて確認してください。</p></div></div>`;}
function keywordTable(){const keywords=state.result.keywords.filter(k=>k.term.toLowerCase().includes(state.keywordQuery.toLowerCase())).slice(0,60);const years=state.result.meta.years;const max=Math.max(1,...keywords.flatMap(k=>k.series.map(s=>s.count)));return `${panelHeader("キーワードの年次推移","KEYWORD FREQUENCY HEATMAP",`<span class="source-pill">${num(keywords.length)} KEYWORDS</span>`)}${keywords.length?`<div class="table-wrap"><table><thead><tr><th>キーワード</th><th class="num">論文数</th>${years.map(y=>`<th class="num">${y}</th>`).join('')}<th class="num">平滑化成長率</th><th>領域</th></tr></thead><tbody>${keywords.map(k=>`<tr><td><button class="keyword-label" data-keyword="${e(k.term)}">${e(k.term)}</button></td><td class="num">${num(k.count)}</td>${years.map(y=>{const value=k.series.find(s=>s.year===y)?.count??0;return `<td class="heatmap-cell"><span class="heatmap-value" style="background:rgba(67,199,170,${value?(.1+.63*value/max).toFixed(3):.025})">${value}</span></td>`;}).join('')}<td class="num ${k.growth_pct<0?'growth-negative':'growth-positive'}">${pct(k.growth_pct)}</td><td><button class="legend-item" data-topic="${e(k.topic_id)}" style="--topic-color:${topicColor(k.topic_id)}"><i class="legend-dot"></i><span>${e(topicFor(k.topic_id)?.label||'—')}</span></button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>出現頻度順 · 最大60語を表示</span><span>LOW <span style="color:#2e655d">▰</span><span style="color:#369785">▰</span><span style="color:#58c7ae">▰</span> HIGH</span></div>`:empty('一致するキーワードがありません','検索語を変更してください。')}`;}
const authorNetworkState={request:0,resultId:null,groupBy:'community',data:null,cache:new Map(),busy:false,error:'',stage:'',attemptedKey:null,cluster:null};
const authorGroupLabels={id:'著者ID',name:'著者名（一致候補）',institution:'大学・所属機関',community:'共著コミュニティ',topic:'研究分野'};
function resetAuthorNetwork(){++authorNetworkState.request;Object.assign(authorNetworkState,{resultId:null,data:null,busy:false,error:'',stage:'',attemptedKey:null,cluster:null});authorNetworkState.cache.clear();}
function currentAuthorNetwork(){return authorNetworkState.resultId===state.result?.id&&authorNetworkState.data?authorNetworkState.data:state.result?.network||{nodes:[],edges:[],clusters:[]};}
function displayedAuthorGroup(){return currentAuthorNetwork().group_by||'topic';}
function authorClusters(network=currentAuthorNetwork()){if(Array.isArray(network.clusters))return network.clusters;return (state.result?.topics||[]).map(topic=>{const members=(network.nodes||[]).filter(node=>node.topic_id===topic.id);return {id:topic.id,label:topic.label,color:topicPaint(topic),node_ids:members.map(node=>node.id),author_count:members.length,paper_count:null,x:members.reduce((sum,node)=>sum+Number(node.x||0),0)/Math.max(1,members.length),y:members.reduce((sum,node)=>sum+Number(node.y||0),0)/Math.max(1,members.length)};}).filter(cluster=>cluster.author_count);}
function authorClusterFor(node){return authorClusters().find(cluster=>cluster.id===(node.cluster_id??node.topic_id));}
function authorNodeColor(node){return color(authorClusterFor(node)?.color||topicColor(node.topic_id));}
function authorNames(node){return [...new Set([node.label,...(Array.isArray(node.names)?node.names:[])].filter(Boolean).map(String))];}
function authorOriginalIds(node){return [...new Set([node.id,...(Array.isArray(node.original_ids)?node.original_ids:[])].filter(Boolean).map(String))];}
function authorAffiliationEntries(node){return (Array.isArray(node.affiliations)?node.affiliations:[]).map(item=>typeof item==='string'?{name:item,paper_count:null,paper_ids:[]}:item).filter(item=>item&&typeof item.name==='string');}
function authorPaperEvidence(node){if(!state.result||!node)return [];if(Array.isArray(node.paper_ids)){const ids=new Set(node.paper_ids);return state.result.papers.filter(paper=>ids.has(paper.id));}const ids=new Set(authorOriginalIds(node));return state.result.papers.filter(paper=>(paper.authors||[]).some(author=>ids.has(String(author.id))));}
function authorIdentityLabel(basis){return ({orcid:'ORCIDによる識別',scopus_id:'Scopus著者IDによる識別',persistent_id:'永続的な著者IDによる識別',provided_id:'提供された著者IDによる識別',explicit_id:'明示された著者IDによる識別',explicit_alias:'明示的なIDの別名対応による識別',explicit_alias_with_name_estimate:'明示的なID対応と名前由来の推定を含む識別',name_estimate:'著者名による推定',name_only:'著者名のみ・同一人物は未確定',name_alias_estimate:'名前の別表記を含む推定'})[basis]||basis||'保存済みの著者識別情報';}
function allCanonicalAuthorNodes(){const network=currentAuthorNetwork();return Array.isArray(network.export_data?.authors)?network.export_data.authors:network.nodes||[];}
function canonicalAuthorLookup(){const nodes=allCanonicalAuthorNodes(),candidates=new Map(),lookup=new Map();for(const node of nodes)for(const alias of authorOriginalIds(node)){const values=candidates.get(alias)||new Map();values.set(node.id,node);candidates.set(alias,values);}for(const [alias,values] of candidates)if(values.size===1)lookup.set(alias,[...values.values()][0]);for(const node of nodes)lookup.set(String(node.id),node);return lookup;}
function findAuthorNode(id){return canonicalAuthorLookup().get(String(id))||state.result?.network?.nodes?.find(node=>node.id===id);}
function filteredAuthorNodes(){const network=currentAuthorNetwork(),query=state.authorQuery.trim().normalize('NFKC').toLocaleLowerCase('ja-JP');return (network.nodes||[]).filter(node=>{if(authorNetworkState.cluster&&(node.cluster_id??node.topic_id)!==authorNetworkState.cluster)return false;if(!query)return true;return [...authorNames(node),...authorOriginalIds(node),...authorAffiliationEntries(node).map(entry=>entry.name),...(Array.isArray(node.original_affiliations)?node.original_affiliations:[]).filter(value=>typeof value==='string')].join(' ').normalize('NFKC').toLocaleLowerCase('ja-JP').includes(query);}).sort((a,b)=>Number(b.count||0)-Number(a.count||0)||String(a.label).localeCompare(String(b.label),'ja'));}
function authorGroupDescription(group){return ({id:'識別可能な著者IDごとに色分けします。名前が同じでもIDが異なる著者は別の点として保持します。',name:'正規化した著者名が一致する候補を同じ色で表示します。同名でも異なるIDは別ノードであり、同一人物との確定ではありません。',institution:'著者自身に明示された所属を使います。複数所属は主表示先で色分けし、全所属は詳細で確認できます。所属未取得の著者も残します。',community:'取得した共著関係から、つながりの密な集団を計算します。点は著者、線は共著論文です。実際の研究室や組織を認定するものではありません。',topic:'各著者の論文に現れる主な研究分野で色分けします。複数の研究分野への参加は著者詳細の年別表で確認できます。'})[group]||'';}
function ensureAuthorNetwork(){if(state.view!=='authors'||!state.result)return;const key=`${state.result.id}:${authorNetworkState.groupBy}`;if(authorNetworkState.busy||authorNetworkState.attemptedKey===key||(authorNetworkState.resultId===state.result.id&&authorNetworkState.data?.group_by===authorNetworkState.groupBy))return;requestAuthorNetwork(authorNetworkState.groupBy);}
async function requestAuthorNetwork(group=authorNetworkState.groupBy,force=false){if(!state.result||!Object.hasOwn(authorGroupLabels,group))return;const resultId=state.result.id,request=++authorNetworkState.request,key=`${resultId}:${group}`;authorNetworkState.groupBy=group;authorNetworkState.cluster=null;authorNetworkState.attemptedKey=key;authorNetworkState.error='';state.author=null;if(authorNetworkState.resultId!==resultId){authorNetworkState.data=null;authorNetworkState.cache.clear();}authorNetworkState.resultId=resultId;const cached=authorNetworkState.cache.get(group);if(cached&&!force){authorNetworkState.data=cached;authorNetworkState.busy=false;if(state.view==='authors')render();return;}authorNetworkState.busy=true;authorNetworkState.stage=`${authorGroupLabels[group]}で共著ネットワークを計算しています…`;if(state.view==='authors')render();const current=()=>request===authorNetworkState.request&&state.result?.id===resultId;try{const job=await post('/api/author-networks',{result_id:resultId,group_by:group});while(current()){const update=await api(`/api/jobs/${encodeURIComponent(job.job_id)}`);if(!current())return;if(update.status==='failed')throw new Error(update.error||'共著ネットワークを計算できませんでした。');if(update.status==='completed'){if(!update.author_network_id)throw new Error('ネットワークの識別子が返りませんでした。');const completed=await api(`/api/author-networks/${encodeURIComponent(update.author_network_id)}`);if(!current())return;if(completed.result_id!==resultId||completed.group_by!==group)throw new Error('別の分析・分類結果が返されたため、表示を中止しました。');authorNetworkState.data=completed;authorNetworkState.cache.set(group,completed);break;}authorNetworkState.stage=update.stage||authorNetworkState.stage;const progress=$('#author-network-progress');if(progress)progress.textContent=authorNetworkState.stage;await new Promise(resolve=>setTimeout(resolve,850));}}catch(error){if(current())authorNetworkState.error=error.message;}finally{if(current()){authorNetworkState.busy=false;if(state.view==='authors')render();}}}
function authorNetworkExports(network){return network.id&&network.result_id===state.result?.id?`<div class="author-network-exports">${[['authors','著者'],['edges','共著関係'],['clusters','クラスタ']].map(([kind,label])=>`<a href="/api/author-networks/${encodeURIComponent(network.id)}/export?kind=${kind}" download>${icon('download')}${label} CSV</a>`).join('')}</div>`:'';}
function authorNetworkStats(network){const stats=network.stats||{},nodes=network.nodes||[],edges=network.edges||[];return `<div class="author-network-stats"><div><span>表示している著者</span><strong>${num(stats.displayed_authors??nodes.length)}<small> / ${num(stats.authors_total??state.result?.summary?.authors??nodes.length)}</small></strong></div><div><span>表示対象内の共著関係</span><strong>${num(stats.displayed_edges??edges.length)}<small> / ${num(stats.edges_total??edges.length)}</small></strong></div><div><span>表示集団のクラスタ</span><strong>${num(stats.clusters_total??authorClusters(network).length)}</strong></div><div><span>全対象著者の所属記録率</span><strong>${stats.affiliation_coverage_pct==null?'—':percent(stats.affiliation_coverage_pct)}</strong></div></div>`;}
function renderAuthors(){const network=currentAuthorNetwork(),actual=displayedAuthorGroup(),legacy=!network.group_by,stats=network.stats||{},nodes=network.nodes||[];return `<div class="author-network-controls"><div><span class="eyebrow">REORGANIZE THE RESEARCH COMMUNITY</span><label for="author-group-by">共著ネットワークの分類基準</label><select id="author-group-by">${Object.entries(authorGroupLabels).map(([id,label])=>`<option value="${id}" ${authorNetworkState.groupBy===id?'selected':''}>${label}</option>`).join('')}</select></div><div><button class="button button-quiet button-small" data-action="author-network-refresh" ${authorNetworkState.busy?'disabled':''}>${icon('refresh')}ネットワークを再計算</button>${authorNetworkExports(network)}</div></div>${authorNetworkState.busy?`<div class="discover-progress author-network-progress" role="status" id="author-network-progress">${e(authorNetworkState.stage)}</div>`:''}${authorNetworkState.error?`<div class="inline-error author-network-error" role="alert">${e(authorNetworkState.error)}<p>表示可能な保存済みネットワークを保持しています。表示中の分類：${e(authorGroupLabels[actual])}${legacy?'（従来の分析）':''}。</p><button class="text-link" data-action="author-network-refresh">再試行 ${icon('refresh')}</button></div>`:''}<div class="author-network-context"><span class="source-pill">${e(authorGroupLabels[actual])}${legacy?' · 保存済み':''}</span><p>${e(authorGroupDescription(actual))}</p>${authorNetworkState.busy&&actual!==authorNetworkState.groupBy?'<small>計算中は直前の分類を表示しています。</small>':''}</div>${authorNetworkStats(network)}<div class="author-explorer-grid"><section class="panel author-network-panel">${panelHeader('研究者の共著ネットワーク','CO-AUTHORSHIP · GROUPED BY EVIDENCE',`<span class="source-pill" id="author-map-count">${num(filteredAuthorNodes().length)} / ${num(nodes.length)} 表示</span>`)}<div id="author-map-container">${authorMap()}</div><div id="author-cluster-legend">${authorClusterLegend()}</div><div class="panel-note">点の大きさ＝論文数、線の太さ＝共著論文数。色と配置は選択した分類に基づく表示用の整理です。距離や面積は研究の近さを表しません。著者名は同姓同名・表記揺れが残るため、識別根拠を確認してください。${network.truncated?` マップは${num(stats.displayed_authors??nodes.length)}著者・${num(stats.displayed_edges??network.edges?.length)}辺に絞って表示しています。`:''}</div></section><section class="panel author-search-panel">${panelHeader('著者・ID・所属を探索','FIND THE PEOPLE BEHIND THE PAPERS')}<div class="author-search-box"><div class="search-box">${icon('search')}<input id="author-search" type="search" value="${e(state.authorQuery)}" placeholder="著者名・ID・大学名で検索" aria-label="表示対象の著者名・ID・所属を検索"></div><p>検索範囲：マップ対象${num(nodes.length)}著者。全著者はCSVで確認できます。</p></div><div id="author-filter-summary">${authorFilterSummary()}</div><div class="author-list" id="author-list">${authorList()}</div></section></div><details class="author-network-methodology"><summary>${icon('info')}収録範囲・識別方法・分類の注意事項</summary><p>著者CSVは全対象著者、共著関係CSVはマップ対象著者間の全共著辺、クラスタCSVはマップ対象著者の分類を出力します。所属には著者への明示的な記録だけを使用し、論文全体の所属を全著者に割り当てません。</p>${fieldNotes([...(network.warnings||[]),...(network.methodology||[])])}</details>`;}
function authorFilterSummary(){const nodes=filteredAuthorNodes(),cluster=authorClusters().find(c=>c.id===authorNetworkState.cluster),filtered=Boolean(state.authorQuery||cluster);return `<div class="author-filter-summary"><span>${num(nodes.length)}著者${cluster?` · ${e(cluster.label)}`:''}</span>${filtered?'<button class="text-link" data-action="author-filter-clear">絞り込みを解除 ×</button>':''}</div>`;}
function authorClusterLegend(){const clusters=authorClusters(),selected=authorNetworkState.cluster;return `<div class="author-cluster-header"><span>クラスタを選んで絞り込み</span>${selected?'<button class="text-link" data-action="author-cluster-clear">全クラスタを表示 ×</button>':''}</div><div class="author-cluster-list">${clusters.map(cluster=>`<button class="author-cluster-chip ${selected===cluster.id?'selected':''}" style="--cluster-color:${color(cluster.color)}" data-author-cluster="${e(cluster.id)}" aria-pressed="${selected===cluster.id}" title="${e(cluster.label)} · ${num(cluster.author_count)}著者"><i></i><span>${e(cluster.label)}</span><b>${num(cluster.author_count)}</b></button>`).join('')||'<p class="field-help">分類情報はまだありません。</p>'}</div>`;}
function updateAuthorFilters(){if(state.view!=='authors')return;const count=$('#author-map-count');if(count)count.textContent=`${num(filteredAuthorNodes().length)} / ${num(currentAuthorNetwork().nodes?.length)} 表示`;const map=$('#author-map-container');if(map)map.innerHTML=authorMap();const list=$('#author-list');if(list)list.innerHTML=authorList();const legend=$('#author-cluster-legend');if(legend)legend.innerHTML=authorClusterLegend();const summary=$('#author-filter-summary');if(summary)summary.innerHTML=authorFilterSummary();}
function authorMap(){const network=currentAuthorNetwork(),nodes=filteredAuthorNodes(),all=network.nodes||[];if(!all.length)return empty('著者情報がありません','著者名・著者IDを含む公開論文またはCSVを読み込むと共著関係を分析できます。');if(!nodes.length)return empty('条件に一致する著者がいません','検索語やクラスタの絞り込みを変更してください。',`<button class="button button-quiet" data-action="author-filter-clear">絞り込みを解除</button>`);const w=860,h=540,pad=58,xy=n=>[pad+clamp(n.x,0,1)*(w-pad*2),pad+clamp(n.y,0,1)*(h-pad*2)],byId=new Map(nodes.map(n=>[n.id,n])),edges=(network.edges||[]).filter(edge=>byId.has(edge.source)&&byId.has(edge.target)),clusters=authorClusters(network).filter(cluster=>nodes.some(node=>(node.cluster_id??node.topic_id)===cluster.id));const occupied=[],nodeLabels=[],clusterLabels=[];if(displayedAuthorGroup()!=='id'){for(const cluster of [...clusters].sort((a,b)=>b.author_count-a.author_count).slice(0,8)){if(cluster.author_count<2)continue;const members=nodes.filter(node=>(node.cluster_id??node.topic_id)===cluster.id),points=members.map(xy),label=String(cluster.label),short=label.length>32?label.slice(0,31)+'…':label,width=Math.min(235,short.length*6.1+20),height=23,cx=points.reduce((sum,p)=>sum+p[0],0)/points.length;const rect={x:clamp(cx-width/2,10,w-width-10),y:clamp(Math.min(...points.map(p=>p[1]))-53,17,h-40),width,height};if(rect.x<240&&rect.y<72)rect.y=73;if(occupied.some(other=>rect.x<other.x+other.width+4&&rect.x+rect.width+4>other.x&&rect.y<other.y+other.height+4&&rect.y+rect.height+4>other.y))continue;occupied.push(rect);clusterLabels.push(`<g class="author-cluster-map-label" data-author-cluster="${e(cluster.id)}" tabindex="0" role="button" aria-label="${e(label)}で絞り込み"><rect x="${rect.x}" y="${rect.y}" width="${width}" height="${height}" rx="4" stroke="${color(cluster.color)}"/><text x="${rect.x+width/2}" y="${rect.y+15}" text-anchor="middle" fill="${color(cluster.color)}">${e(short)}</text><title>${e(label)} · ${num(cluster.author_count)}著者</title></g>`);}}for(const node of nodes.slice(0,Math.min(nodes.length,11))){const [x,y]=xy(node),label=String(displayedAuthorGroup()==='id'?node.id:node.label||node.id),short=label.length>27?label.slice(0,26)+'…':label,width=Math.min(190,short.length*5.4+14),height=20;const candidates=[{x:x-width/2,y:y-29},{x:x-width/2,y:y+18},{x:x+19,y:y-10},{x:x-width-19,y:y-10}].map(rect=>({...rect,x:clamp(rect.x,10,w-width-10),y:clamp(rect.y,18,h-height-14),width,height}));const fits=rect=>!occupied.some(other=>rect.x<other.x+other.width+3&&rect.x+rect.width+3>other.x&&rect.y<other.y+other.height+3&&rect.y+rect.height+3>other.y);const rect=candidates.find(fits);if(!rect)continue;occupied.push(rect);nodeLabels.push(`<g class="author-node-label" data-author="${e(node.id)}" tabindex="0" role="button" aria-label="${e(label)}の詳細"><rect x="${rect.x}" y="${rect.y}" width="${width}" height="${height}" rx="4"/><text x="${rect.x+width/2}" y="${rect.y+13}" text-anchor="middle">${e(short)}</text><title>${e(label)}</title></g>`);}return `<div class="map-stage large author-map-stage"><div class="map-corner">COLLABORATION SPACE<br>${num(nodes.length)} PEOPLE · ${num(edges.length)} LINKS${authorNetworkState.cluster?'<br>SELECTED CLUSTER':''}</div><svg class="map-svg" viewBox="0 0 ${w} ${h}" role="group" aria-label="${e(authorGroupLabels[displayedAuthorGroup()])}で分類した共著ネットワーク"><g>${clusters.filter(cluster=>cluster.author_count>1).map(cluster=>{const members=nodes.filter(node=>(node.cluster_id??node.topic_id)===cluster.id),points=members.map(xy);if(!points.length)return '';const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,rx=Math.max(31,(Math.max(...xs)-Math.min(...xs))/2+30),ry=Math.max(31,(Math.max(...ys)-Math.min(...ys))/2+30);return `<ellipse class="author-cluster-halo" cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${color(cluster.color)}" fill-opacity=".035" stroke="${color(cluster.color)}" stroke-opacity=".2" stroke-dasharray="3 6"/>`;}).join('')}${edges.map(edge=>{const a=byId.get(edge.source),b=byId.get(edge.target),p=xy(a),q=xy(b),same=(a.cluster_id??a.topic_id)===(b.cluster_id??b.topic_id),width=Math.min(4,.5+Math.sqrt(Number(edge.weight)||0)*.5);return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${same?authorNodeColor(a):'#7d91a7'}" stroke-width="${width}" opacity="${same?'.35':'.16'}"><title>${e(a.label)} ↔ ${e(b.label)} · 共著${num(edge.weight)}論文</title></line>`;}).join('')}${nodes.map(node=>{const [x,y]=xy(node),known=node.citation_known_papers??knownCitations(authorPaperEvidence(node)).length,cluster=authorClusterFor(node),c=authorNodeColor(node),selected=node.id===state.author,r=5+Math.min(11,Math.sqrt(Number(node.count)||0)*1.5);return `${selected?`<circle cx="${x}" cy="${y}" r="${r+5}" fill="none" stroke="#d8f5eb" stroke-opacity=".7" stroke-width="1"/>`:''}<circle class="map-node" cx="${x}" cy="${y}" r="${r}" fill="${c}" fill-opacity=".7" stroke="${c}" stroke-width="1.6" data-author="${e(node.id)}" tabindex="0" role="button" aria-label="${e(node.label)}、${num(node.count)}論文、${e(cluster?.label||'分類不明')}" data-tooltip="${e(node.label)}" data-tooltip-sub="${e(cluster?.label||'分類不明')} · ${num(node.count)}論文 · ${known?`${num(node.citations)}被引用`:'被引用数未取得'}"><title>${e(node.label)} · ${e(cluster?.label||'分類不明')} · ${e(authorIdentityLabel(node.identity_basis))}</title></circle>`;}).join('')}${nodeLabels.join('')}${clusterLabels.join('')}</g></svg></div>`;}
function authorList(){const nodes=filteredAuthorNodes();return nodes.map(node=>{const cluster=authorClusterFor(node),affiliations=authorAffiliationEntries(node),ids=authorOriginalIds(node),name=String(node.label||node.id);return `<button class="author-row ${state.author===node.id?'selected':''}" data-author="${e(node.id)}"><span class="author-avatar" style="--author-color:${authorNodeColor(node)}">${e(initials(name))}</span><span><strong>${e(name)}</strong><small class="author-cluster-name" style="color:${authorNodeColor(node)}">${e(cluster?.label||'分類不明')}</small><small>${e(affiliations[0]?.name||'著者の所属未取得')}</small><small class="author-id-preview">${e(ids[0])}</small></span><span>${num(node.count)}<small>論文</small></span></button>`;}).join('')||empty('著者が見つかりません','検索語やクラスタの条件を変更してください。');}
function initials(name){return name.split(/[\s,]+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function renderCitations(){const r=state.result,annual=state.citationMode==='annual',coverage=r.meta.citation_history_coverage;const values=r.timeline.map(t=>({year:t.year,value:annual?t.annual_citations:((r.meta.papers_truncated?t.citation_known_count>0:knownCitations(r.papers.filter(p=>p.year===t.year)).length)?t.citations:null),tooltip:annual?`取得範囲内の年別引用イベント${t.annual_coverage!=null?` · ${num(t.annual_observed_papers)} / ${num(t.annual_eligible_papers)} 論文を取得 (${percent(t.annual_coverage)})`:''}`:'この年に出版された論文の、取得時点の累積被引用数'}));const hasAnnual=r.timeline.some(t=>t.annual_citations!=null);const top=r.meta.papers_truncated?(r.top_cited_papers||[]):[...r.papers].filter(p=>p.citations!=null).sort((a,b)=>b.citations-a.citations).slice(0,6);const observed=values.filter(v=>v.value!=null).reduce((a,p)=>a+p.value,0);return `<div class="data-callout ${coverage<100?'warning':''}">${icon('info')}<div><strong>引用履歴がある論文の割合：${percent(coverage)}</strong><p>公開サイトやCSVの被引用数は取得時点の累積値です。集計元によって収録範囲が異なり、複数の計数元の値は足し合わせません。引用の増加を分析するには、別途、論文ごとの年別新規引用数が必要です。ここでの割合は、年別履歴が1年分以上ある論文の割合です。全期間の欠測のなさを意味せず、各年の収録率は棒のツールチップで確認できます。未取得年を0件として扱いません。</p></div><button class="button button-quiet button-small" data-action="citation-upload">引用履歴を追加 ${icon('plus')}</button></div><div class="citation-grid"><section class="panel">${panelHeader("引用の時系列","CITATION ACTIVITY")}<div style="padding:0 20px 20px"><div class="segmented"><button data-citation-mode="annual" class="${annual?'active':''}">引用イベント年別</button><button data-citation-mode="cohort" class="${!annual?'active':''}">出版年別・累積引用数</button></div></div><div class="metric-inline"><div><small>${annual?'取得済みの引用イベント合計':'対象論文の累積被引用数'}</small><strong>${(annual&&!hasAnnual)||(!annual&&!(r.meta.papers_truncated?r.meta.citation_snapshot_coverage>0:knownCitations(r.papers).length))?'—':num(observed)}<span>引用</span></strong></div><div><small>${annual?'引用履歴がある論文の割合':'集計対象'}</small><strong>${annual?percent(coverage):num(r.summary.papers)}<span>${annual?'':'論文'}</span></strong></div></div>${annual&&!hasAnnual?empty('年別の引用履歴がまだありません','「引用履歴を追加」から EID・Year・Citations を含むCSVを読み込むと、引用の時間的な変化を分析できます。'):`<div class="chart-wrap citation-chart">${makeLineChart([{label:annual?'取得済み新規引用数':'出版年別の累積被引用数',color:annual?'#58e0c5':'#77a8fc',values}],r.meta.years,{height:300,unit:'引用数',bar:true})}</div>`}<div class="panel-note">${annual?'横軸は引用が発生した年。部分的な履歴がある年の合計は、取得済み論文の範囲に限定されます。':'横軸は論文が出版された年。棒の高さは、その年の論文が現在までに受けた引用の累積です。年別の引用イベント数とは異なります。'}</div></section><section class="panel">${panelHeader("影響の大きい論文","MOST CITED PAPERS")}<div style="padding:0 20px 12px">${evidenceList(top.map(p=>p.id),6)}</div></section></div><section class="panel">${panelHeader("技術領域ごとの引用影響","CITATION IMPACT BY TOPIC")}<div class="table-wrap"><table><thead><tr><th>技術トピック</th><th class="num">論文数</th><th class="num">累積被引用数</th><th class="num">1論文あたり</th><th class="num">年別引用の変化</th></tr></thead><tbody>${[...r.topics].sort((a,b)=>b.citations-a.citations).map(t=>`<tr><td><button class="legend-item" data-topic="${e(t.id)}" style="--topic-color:${topicPaint(t)}"><i class="legend-dot"></i><span>${e(t.label)}</span></button></td><td class="num">${num(t.count)}</td><td class="num">${num(topicCitationTotal(t.id))}</td><td class="num">${topicCitationMean(t.id)}</td><td class="num ${t.citation_growth_pct<0?'negative':'positive'}">${pct(t.citation_growth_pct)}</td></tr>`).join('')}</tbody></table></div><div class="panel-note" style="padding-top:14px">累積被引用数は取得済みの値の合計です。1論文あたりの被引用数は、被引用数を取得できた論文だけを分母にしています。年別引用の変化は、比較できる引用履歴が揃う場合に表示します。引用の遅れや分野・出版年の差は残ります。</div></section>`;}
function renderForecasts(){const r=state.result,eligible=classifiedTopics().filter(t=>t.forecast?.length),selected=activeTopic(),t=eligible.find(t=>t.id===selected?.id)||eligible[0];if(!t&&r.meta.annual_comparison_available===false)return empty('年次データが不足しています','収録年が1年だけ、または分析期間が1年のみのため、出版数の予測を表示していません。複数年の論文データを追加してください。','<button class="button button-primary" data-action="upload">論文データを追加</button>');if(!t)return empty('予測できる分類済みテーマがありません','未分類の論文はテーマ別の数値予測に含めません。抽出方法・テーマ数・最小テーマサイズや対象期間を見直してください。','<button class="button button-primary" data-action="settings">分析設定を見直す</button>');const series=t.series.map(s=>({year:s.year,value:s.count})),future=t.forecast||[],years=[...r.meta.years,...future.map(f=>f.year)],last=series.at(-1);const band=last?[{year:last.year,lower:last.value,upper:last.value},...future]:future;return `<div class="forecast-controls">${eligible.map(topic=>`<button class="forecast-topic ${topic.id===t.id?'active':''}" style="--topic-color:${topicPaint(topic)}" data-forecast-topic="${e(topic.id)}"><i class="legend-dot"></i>${e(topic.label)}</button>`).join('')}</div><div class="forecast-grid"><div><section class="panel">${panelHeader(isSampled()?"取得集合の出版数を外挿":"研究活動の予測シナリオ",isSampled()?"SAMPLED CORPUS EXTRAPOLATION":"EXPLORATORY PUBLICATION FORECAST",`<span class="source-pill">+${r.meta.forecast_horizon} YEARS</span>`)}<div class="metric-inline"><div><small>直近年の出版論文数</small><strong>${num(last?.value)}<span>論文</span></strong></div><div><small>${future.at(-1)?.year||'将来'}年の中心シナリオ</small><strong style="color:#91b7fd">${num(future.at(-1)?.value)}<span>論文</span></strong></div></div><div class="chart-legend"><span><i class="line-key" style="background:${topicPaint(t)}"></i>実績</span><span><i class="line-key dashed"></i>予測</span><span><i class="line-key" style="background:#738499"></i>前年据え置き</span></div><div class="chart-wrap forecast-chart">${makeLineChart([{label:'出版論文数の実績',color:t.color,values:series,area:true},{label:'前年据え置きベースライン',color:'#738499',dashed:true,values:[last,...future.map(f=>({year:f.year,value:last?.value}))].filter(Boolean)},{label:'出版数の中心シナリオ',color:'#77a8fc',dashed:true,values:[last,...future.map(f=>({year:f.year,value:f.value,tooltip:`探索的な幅：${num(f.lower)}–${num(f.upper)} 論文（確率区間ではありません）`}))].filter(Boolean)}],years,{height:310,forecastStart:r.meta.end_year,unit:'論文数',band})}</div><div class="panel-note">${isSampled()?'年・月ごとの取得枠内で抽出した集合の外挿です。検索結果全体の論文数・研究成長は予測していません。':''}青い帯は探索的なシナリオ幅です。統計的に校正された信頼区間・確率ではありません。未来の出版数以外の成果や市場規模は予測していません。</div></section><div class="data-callout" style="margin-top:18px">${icon('info')}<div><strong>短い時系列には、複数の未来があります。</strong><p>出版数の伸びは関心の高まりを示す一つの手掛かりです。過去の検証誤差と前年据え置き予測を比較し、急な変化・データ欠損・研究領域の分類による影響も確認してください。</p></div></div><div class="llm-card"><div class="eyebrow">OPTIONAL · SBERT × LLM</div><h3>数値が捉えた変化を、次の問いへ。</h3><p style="margin-top:7px">Sentence-BERT（SBERT）を選ぶと、文章の意味の類似性を分析に利用できます。LLMは観測結果を根拠に検証可能な仮説を補足します。外部APIには選択した論文のタイトル・抄録とトピック指標を送信します。</p><button class="button button-quiet button-small" data-action="insights">${icon('sparkles')}仮説と根拠を確認</button></div></div>${topicDetail(t,true)}</div>`;}
function renderPapers(){const years=state.result.meta.years;return `${state.paperAuthor?`<div class="paper-author-filter">著者ID ${e(state.paperAuthor)} で絞り込み <button class="text-link" data-action="paper-author-clear">解除</button></div>`:''}<div class="filter-bar"><div class="search-box">${icon('search')}<input id="paper-search" type="search" maxlength="500" value="${e(state.query)}" placeholder="タイトル、抄録、著者、キーワードで検索" aria-label="論文を検索"></div><select id="paper-topic" aria-label="技術トピックで絞り込み"><option value="all">すべての技術トピック</option>${state.result.topics.map(t=>`<option value="${e(t.id)}" ${state.paperTopic===t.id?'selected':''}>${e(t.label)}</option>`).join('')}</select><select id="paper-year" aria-label="出版年で絞り込み"><option value="all">すべての出版年</option>${[...years].reverse().map(y=>`<option value="${y}" ${Number(state.paperYear)===y?'selected':''}>${y}年</option>`).join('')}</select><select id="paper-sort" aria-label="論文の並び順"><option value="citations" ${state.paperSort==='citations'?'selected':''}>被引用数順</option><option value="year" ${state.paperSort==='year'?'selected':''}>新しい順</option><option value="title" ${state.paperSort==='title'?'selected':''}>タイトル順</option></select></div><section class="panel" id="papers-table">${paperTable()}</section>`;}
function filteredPapers(){const q=state.query.toLowerCase().trim();return state.result.papers.filter(p=>(!state.paperAuthor||p.authors.some(a=>String(a.id)===state.paperAuthor))&&(state.paperTopic==='all'||p.topic_id===state.paperTopic)&&(state.paperYear==='all'||p.year===Number(state.paperYear))&&(!q||[p.title,p.abstract,...p.authors.map(a=>a.name),...p.keywords].join(' ').toLowerCase().includes(q))).sort((a,b)=>state.paperSort==='year'?b.year-a.year:state.paperSort==='title'?a.title.localeCompare(b.title):((b.citations??-1)-(a.citations??-1)));}
function paperTable(){const remote=Boolean(state.result.meta?.papers_truncated),data=state.paperRemote;if(remote&&data?.key!==paperRequestKey())return '<div class="paper-loading" role="status">全論文から検索しています…</div>';if(remote&&data?.error)return empty('論文を読み込めませんでした',data.error,'<button class="button button-quiet" data-action="paper-reload">再試行</button>');const all=remote?data.items:filteredPapers(),total=remote?Number(data.total):all.length,pageSize=20,pages=Math.ceil(total/pageSize);state.paperPage=clamp(state.paperPage,0,Math.max(0,pages-1));const shown=remote?all:all.slice(state.paperPage*pageSize,(state.paperPage+1)*pageSize);return `${panelHeader('論文エビデンス','SOURCE PAPERS',`<span class="source-pill">${num(total)} RESULTS</span>`)}${shown.length?`<div class="table-wrap"><table><thead><tr><th>タイトル / 著者</th><th>技術トピック</th><th class="num">出版年</th><th class="num">被引用数</th><th>掲載誌 / 取得元</th></tr></thead><tbody>${shown.map(p=>`<tr><td><button class="paper-title" data-paper="${e(p.id)}">${e(p.title)}</button><div class="paper-authors">${e(p.authors.slice(0,3).map(a=>a.name).join(' · '))}${p.authors.length>3?` ほか${p.authors.length-3}名`:''}</div></td><td><button class="legend-item" data-topic="${e(p.topic_id)}" style="--topic-color:${topicColor(p.topic_id)}"><i class="legend-dot"></i><span>${e(topicFor(p.topic_id)?.label||'—')}</span></button></td><td class="num">${p.year}</td><td class="num">${p.citations==null?'—':num(p.citations)}<small class="citation-source">${e(citationOrigin(p))}</small></td><td><div class="paper-source">${e(p.source||'—')}</div><div class="paper-provider">${paperProviders(p).map(name=>`<span class="source-pill">${e(name)}</span>`).join('')}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${num(total)}件中 ${num(state.paperPage*pageSize+1)}–${num(Math.min((state.paperPage+1)*pageSize,total))}件を表示</span><div class="pagination"><button data-page="prev" ${state.paperPage===0?'disabled':''}>← 前へ</button><span>${state.paperPage+1} / ${pages}</span><button data-page="next" ${state.paperPage>=pages-1?'disabled':''}>次へ →</button></div></div>`:empty('一致する論文がありません','検索語やトピック・出版年の条件を変更してください。')}`;}
async function showPaper(id){const resultId=state.result?.id,token=state.paperDetailRequest=(state.paperDetailRequest||0)+1;if(!resultId)return;$('#detail-eyebrow').textContent='PAPER EVIDENCE';$('#detail-title').textContent='研究の根拠をたどる';$('#detail-body').innerHTML='<p class="paper-loading" role="status">原典を読み込んでいます…</p>';openDialog('#detail-dialog');let p;try{p=await getPaper(id,resultId);}catch(error){if(token===state.paperDetailRequest&&state.result?.id===resultId)$('#detail-body').innerHTML=empty('原典を読み込めませんでした',error.message);return;}if(!p||token!==state.paperDetailRequest||state.result?.id!==resultId||!$('#detail-dialog').open)return;$("#detail-eyebrow").textContent="PAPER EVIDENCE";$("#detail-title").textContent="研究の根拠をたどる";const years=Object.keys(p.citation_history||{}).map(Number).sort((a,b)=>a-b);const doi=String(p.doi||'').replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'');$("#detail-body").innerHTML=`<h3 class="detail-title">${e(p.title)}</h3><div class="detail-meta"><span class="source-pill">${e(p.publication_date||`${p.year}年・月不明`)}</span><span>${p.citations==null?'被引用数未取得':`${num(p.citations)} 被引用`}</span><span>·</span><span>${e(p.source||'掲載誌未取得')}</span></div>${provenanceHTML(p)}${citationSnapshotsHTML(p)}<p class="muted">${p.authors.map(a=>`<button class="text-link" data-author="${e(a.id)}">${e(a.name)}</button>`).join(' · ')||'著者未取得'}</p><div class="tags">${p.keywords.map(k=>`<span class="tag">${e(k)}</span>`).join('')}</div><div class="detail-section"><h3>抄録 <span class="subtle-label">ABSTRACT</span></h3><p class="abstract">${e(p.abstract||'この論文には抄録が含まれていません。抄録を取得できる別の公開サイトや、抄録を含むCSVで補完できます。')}</p>${doi?`<a class="doi-link" href="https://doi.org/${encodeURI(doi).replace(/["'<>]/g,encodeURIComponent)}" target="_blank" rel="noopener noreferrer">DOI: ${e(doi)} ${icon('external')}</a>`:''}</div><div class="detail-section"><h3>所属する技術トピック</h3><button class="legend-item" data-detail-topic="${e(p.topic_id)}" style="--topic-color:${topicColor(p.topic_id)}"><i class="legend-dot"></i><span>${e(topicFor(p.topic_id)?.label||'—')} ↗</span></button></div>${years.length?`<div class="detail-section"><h3>年別の新規引用数</h3><div class="chart-wrap">${makeLineChart([{label:'取得済みの新規引用数',color:'#58e0c5',values:years.map(year=>({year,value:p.citation_history[String(year)]}))}],years,{height:180,unit:'引用数',bar:true})}</div></div>`:''}<p class="field-help" style="margin-top:23px">識別子：${e(p.id)}${state.result.meta.is_demo?' · 合成・テストデータを含むデータセット':''}</p>`;openDialog('#detail-dialog');}
function authorEvidenceButton(ids,label){return Array.isArray(ids)&&ids.length?`<button class="text-link" data-author-evidence="${e(JSON.stringify(ids))}">${e(label)} ${icon('arrow')}</button>`:'';}
function showAuthorEvidence(ids){if(!state.result)return;const author=findAuthorNode(state.author);$('#detail-eyebrow').textContent='AUTHOR AFFILIATION EVIDENCE';$('#detail-title').textContent='所属が明示された論文';$('#detail-body').innerHTML=`${author?`<button class="text-link field-back-link" data-author="${e(author.id)}">← ${e(author.label)} の著者詳細に戻る</button>`:''}${evidenceList(ids,40)}`;openDialog('#detail-dialog');}
function showAuthor(id){if(!state.result)return;let node=findAuthorNode(id);if(!node){const papers=state.result.papers.filter(paper=>(paper.authors||[]).some(author=>String(author.id)===String(id)));if(!papers.length)return;const matches=papers.flatMap(paper=>(paper.authors||[]).filter(author=>String(author.id)===String(id)));const affiliations=new Map();for(const paper of papers){const seen=new Set();for(const author of (paper.authors||[]).filter(author=>String(author.id)===String(id)))for(const name of (Array.isArray(author.affiliations)?author.affiliations:[]).filter(value=>typeof value==='string')){if(seen.has(name))continue;seen.add(name);const entry=affiliations.get(name)||{name,paper_count:0,paper_ids:[]};entry.paper_count++;entry.paper_ids.push(paper.id);affiliations.set(name,entry);}}node={id,label:matches[0]?.name||id,names:[...new Set(matches.map(author=>author.name).filter(Boolean))],original_ids:[id],paper_ids:papers.map(paper=>paper.id),count:papers.length,affiliations:[...affiliations.values()],identity_basis:String(id).startsWith('name:')?'name_estimate':'provided_id',citations:knownCitations(papers).length?knownCitations(papers).reduce((sum,paper)=>sum+paper.citations,0):null,topic_id:papers[0].topic_id};}state.author=node.id;const papers=authorPaperEvidence(node),cluster=authorClusterFor(node),names=authorNames(node),affiliations=authorAffiliationEntries(node),collaborators=new Map(),canonicalLookup=canonicalAuthorLookup();for(const paper of papers){const seen=new Set();for(const author of paper.authors||[]){const rawId=String(author.id||''),candidate=canonicalLookup.get(rawId),canonicalId=candidate?.id||rawId;if(!rawId||canonicalId===node.id||seen.has(canonicalId))continue;seen.add(canonicalId);const entry=collaborators.get(canonicalId)||{id:canonicalId,name:candidate?.label||author.name||rawId,count:0};entry.count++;collaborators.set(canonicalId,entry);}}const known=knownCitations(papers),partial=Boolean(state.result.meta?.papers_truncated),citationCount=partial?(node.citation_known_papers>0?node.citations:null):known.length?known.reduce((sum,paper)=>sum+Number(paper.citations||0),0):null;$('#detail-eyebrow').textContent='RESEARCHER IDENTITY & EVIDENCE';$('#detail-title').textContent='研究者の識別とつながり';$('#detail-body').innerHTML=`<div class="author-detail-banner"><span class="author-avatar" style="--author-color:${authorNodeColor(node)}">${e(initials(String(node.label||node.id)))}</span><div><h3>${e(node.label||node.id)}</h3><p>${e(cluster?.label||node.cluster_label||topicFor(node.topic_id)?.label||'研究者')}</p></div></div><div class="author-identity-notice"><strong>${e(authorIdentityLabel(node.identity_basis))}</strong><p>同名の著者が同一人物とは限りません。異なる永続IDは別ノードとして扱い、名前だけで照合した記録には同姓同名・表記揺れの不確実性が残ります。</p></div>${partial?`<p class="paper-evidence-scope">論文数・引用数は著者の集計値です。以下の共著者・活動年・時系列は画面に読み込まれた根拠論文の範囲です。<button class="text-link" data-paper-author="${e(authorOriginalIds(node)[0]||node.id)}">著者IDの全論文を検索 ↗</button></p>`:''}<div class="topic-metrics"><div><span>根拠となる論文</span><strong>${num(partial?(node.count??papers.length):papers.length)}</strong><small> 件</small></div><div><span>共著者の識別レコード</span><strong>${num(collaborators.size)}</strong><small> 件</small></div><div><span>累積被引用数</span><strong>${num(citationCount)}</strong></div><div><span>活動年</span><strong style="font-size:16px">${[...new Set(papers.map(paper=>paper.year))].sort().map(e).join(' · ')||'—'}</strong></div></div><div class="author-identity-grid"><section><h3>元の著者ID</h3><div class="author-identifier-list">${authorOriginalIds(node).map(value=>`<code>${e(value)}</code>`).join('')}</div></section><section><h3>記録された名前・別表記</h3><div class="tags">${names.map(name=>`<span class="tag">${e(name)}</span>`).join('')||'<span class="field-help">名前未取得</span>'}</div></section></div><div class="detail-section"><h3>著者に明示された所属 <span class="subtle-label">EXPLICIT AUTHOR AFFILIATIONS</span></h3><p>論文全体の所属を全著者へ配分していません。複数所属がある場合、マップでは主表示先を使い、ここではすべての明示記録を示します。</p>${affiliations.length?`<div class="author-affiliation-list">${affiliations.map(entry=>`<div><div><strong>${e(entry.name)}</strong><small>${entry.paper_count==null?'明示的な所属記録':`${num(entry.paper_count)}論文に記載`}</small></div>${authorEvidenceButton(entry.paper_ids,'所属の根拠')}</div>`).join('')}</div>`:'<div class="author-affiliation-empty">この著者の所属は未取得です。論文の所属欄だけでは、この著者が所属する大学を確定できません。</div>'}${Array.isArray(node.original_affiliations)&&node.original_affiliations.filter(value=>typeof value==='string').length?`<details class="author-original-affiliations"><summary>所属の元表記を確認</summary><ul>${node.original_affiliations.filter(value=>typeof value==='string').map(value=>`<li>${e(value)}</li>`).join('')}</ul></details>`:''}</div>${authorTopicTimeline(papers)}<div class="detail-section"><h3>主要な共著者</h3><div class="tags">${[...collaborators.values()].sort((a,b)=>b.count-a.count).slice(0,18).map(author=>`<button class="tag" data-author="${e(author.id)}">${e(author.name)} · ${num(author.count)}論文</button>`).join('')||'<span class="field-help">共著者の記録がありません。</span>'}</div></div><div class="detail-section"><h3>論文エビデンス</h3><p class="field-help">この著者に紐づく論文の識別子から原典を確認できます。${num(papers.length)}件中、被引用数順に最大20件を表示します。</p>${evidenceList([...papers].sort((a,b)=>(b.citations||0)-(a.citations||0)).map(paper=>paper.id),20)}</div>`;openDialog('#detail-dialog');if(state.view==='authors')updateAuthorFilters();}
function authorTopicTimeline(papers){
 const years=state.result.meta.years,topics=state.result.topics.filter(t=>papers.some(p=>p.topic_id===t.id));const counts=topics.map(t=>({topic:t,values:years.map(year=>papers.filter(p=>p.topic_id===t.id&&p.year===year).length)}));const max=Math.max(1,...counts.flatMap(row=>row.values));
 return `<div class="detail-section"><h3>研究領域の変化 <span class="subtle-label">TOPICS OVER TIME</span></h3><p class="field-help">この著者が参加した論文を、出版年と技術トピックで集計しています。色の濃さは論文数です。</p><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>技術トピック</th>${years.map(y=>`<th class="num">${y}</th>`).join('')}</tr></thead><tbody>${counts.map(row=>`<tr><td><span class="legend-item" style="--topic-color:${color(row.topic.color)}"><i class="legend-dot"></i><span>${e(row.topic.label)}</span></span></td>${row.values.map(v=>`<td class="heatmap-cell"><span class="heatmap-value" style="background:rgba(67,199,170,${v?(.1+.6*v/max).toFixed(3):.025})">${v}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
}
async function loadInsights(useLLM=false,question="",specific=false){if(!state.result||(useLLM&&state.insightBusy))return;if(useLLM&&!state.status?.llm_configured){message('LLM APIの接続設定が必要です。分析設定をご確認ください。',true);return;}state.insightBusy=true;const request=++state.insightRequest;state.insightTopic=specific?state.topic:null;state.insight=null;const resultId=state.result.id;const payload={result_id:resultId,use_llm:useLLM};if(specific&&state.topic)payload.topic_id=state.topic;if(question)payload.question=question;if(state.view==='overview'&&$('#overview-insights'))$('#overview-insights').innerHTML=insightPreview();if($('#insight-detail-content'))$('#insight-detail-content').innerHTML='<p class="muted">根拠を整理しています…</p>';try{const insight=await post('/api/insights',payload);if(state.result?.id!==resultId||request!==state.insightRequest)return;state.insight=insight;}catch(error){message(error.message,true);}finally{if(state.result?.id===resultId&&request===state.insightRequest){state.insightBusy=false;if(state.view==='overview'&&$('#overview-insights'))$('#overview-insights').innerHTML=insightPreview();if($('#insight-detail-content'))$('#insight-detail-content').innerHTML=insightDetailContent();}}}
function insightDetailContent(){const d=state.insight;if(state.insightBusy)return '<div class="skeleton"></div><div class="skeleton"></div><p class="muted">分析結果の根拠を整理しています…</p>';if(!d)return '<p class="muted">まだ洞察がありません。下のボタンで分析結果を読み解けます。</p>';return `<span class="source-pill">${d.mode==='llm'?`LLM · ${e(d.model||'API')}`:'LOCAL · 計測値から生成'}</span><h3 class="detail-title" style="margin-top:15px">${e(d.headline)}</h3><div class="detail-section"><h3>観測された変化</h3><ul class="insight-list">${d.findings.map(f=>`<li>${e(f)}</li>`).join('')}</ul></div>${d.hypotheses.length?`<div class="detail-section"><div class="hypothesis-label">HYPOTHESES · 未検証の仮説</div><ul class="insight-list">${d.hypotheses.map(f=>`<li>${e(f)}</li>`).join('')}</ul></div>`:''}<div class="detail-section"><h3>根拠となる論文</h3>${evidenceList(d.evidence_ids,5)}</div>${d.caveats.length?`<div class="detail-section"><h3>解釈する際の注意</h3><ul class="insight-list">${d.caveats.map(f=>`<li>${e(f)}</li>`).join('')}</ul></div>`:''}`;}
function showInsights(){if(!state.result)return;$("#detail-eyebrow").textContent="EVIDENCE → HYPOTHESIS";$("#detail-title").textContent="シグナルを、次の問いに変える";$("#detail-body").innerHTML=`<div id="insight-detail-content">${insightDetailContent()}</div><div class="detail-section"><h3>根拠をもとに、仮説を深める</h3><p>LLMを実行すると、トピックの指標と選択された論文のタイトル・抄録をOpenAI APIに送信します。LLMは数値予測を書き換えず、観測結果から検証可能な仮説を補足します。</p><div class="insight-question"><input type="text" id="insight-question" placeholder="例：この領域の次の研究課題は？" aria-label="LLMへの追加の問い"><button class="button button-primary" data-action="llm" ${state.status.llm_configured?'':'disabled'}>${icon('sparkles')}LLMで仮説を生成</button></div><p class="field-help">${state.status.llm_configured?'API接続済み · 外部送信はこのボタンを押したときのみ':'API未接続 · 分析設定の「LLM・プロキシ接続を設定」でAPIキーとモデルを保存すると利用できます。'}</p><button class="text-link" style="margin-top:14px" data-action="local-insights">ローカルの洞察を再生成 ${icon('refresh')}</button></div>`;openDialog('#detail-dialog');const target=state.view!=='overview'?state.topic:null;if(state.insightTopic!==target||(!state.insight&&!state.insightBusy))loadInsights(false,'',target!==null);}
function modelDetailsHTML(meta){const details=meta.topic_model_details;if(!details||typeof details!=='object'||Array.isArray(details))return '';return `<details class="model-run-details"><summary>テーマ抽出の実行情報</summary><div class="table-wrap"><table><tbody>${Object.entries(details).map(([key,value])=>`<tr><th>${e(key)}</th><td>${e(typeof value==='object'?JSON.stringify(value):String(value))}</td></tr>`).join('')}</tbody></table></div></details>`;}
function showMethodology(){if(!state.result)return;const r=state.result;$("#detail-eyebrow").textContent="TRANSPARENCY & LIMITATIONS";$("#detail-title").textContent="分析手法とデータの限界";$("#detail-body").innerHTML=`<div class="topic-metrics" style="margin-top:0"><div><span>抄録カバレッジ</span><strong>${percent(r.meta.abstract_coverage)}</strong></div><div><span>引用履歴がある論文の割合</span><strong>${percent(r.meta.citation_history_coverage)}</strong></div></div><div class="model-result-summary"><strong>${e(analysisMethodLabel(r.meta))}</strong><span>マップの表現：${e(mapRepresentationLabel(r.meta))}</span><span>${e(r.meta.embedding_model||'')}</span></div><p class="muted">${r.meta.start_year}–${r.meta.end_year} · ${num(r.meta.paper_count)}論文${r.meta.is_demo?' · 合成・テストデータ':''}</p>${modelDetailsHTML(r.meta)}<ul class="method-list">${(r.methodology||[]).map(m=>`<li>${e(m)}</li>`).join('')}</ul>${r.meta.warnings?.length?`<div class="detail-section"><h3>データと条件に関する注意事項</h3><ul class="method-list">${r.meta.warnings.map(m=>`<li>${e(m)}</li>`).join('')}</ul></div>`:''}<div class="detail-section"><h3>観測と予測の区別</h3><p>シグナルスコアは探索のためのヒューリスティックです。将来の予測値は出版数の時系列に基づき、LLMの仮説は補助的な解釈です。技術が実用化する時期や、その成功確率を算出したものではありません。</p></div>`;openDialog('#detail-dialog');}
function datasetCardHTML(d){return `<div class="dataset-entry"><button class="dataset-card" data-dataset="${e(d.id)}">${icon('database')}<div><strong>${e(d.name)}</strong><small>${num(d.paper_count)} 論文 · ${e(new Date(d.created_at).toLocaleString('ja-JP',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}${d.is_demo?' · 合成・テスト':''}</small></div><span>分析 ${icon('arrow')}</span></button>${!d.is_demo?`<button class="text-link dataset-append" data-dataset-append="${e(d.id)}">CSVを継ぎ足す（分析せずに開く） ${icon('plus')}</button>`:''}</div>`;}
function openDatasetForAppend(id){if(state.importBusy){message('CSVを読み込んでいます。完了までお待ちください。');return;}const dataset=state.status?.datasets?.find(item=>item.id===id);if(!dataset)return;++state.selectionVersion;state.dataset=dataset;applyDatasetAnalysisDefaults(dataset);updateDataset();closeDialogs();showStoredDataset();showUpload();$('#csv-after-import').value='save';updateUploadMode(true);}
async function showDatasets(){try{await refreshStatus();$('#dataset-list').innerHTML=state.status.datasets.map(datasetCardHTML).join('')||empty('データセットはまだありません','公開論文検索、手元のCSV、合成デモから始められます。');openDialog('#datasets-dialog');}catch(error){message(error.message,true);}}
function showUpload(mode='papers'){if(state.importBusy){message('CSVを読み込んでいます。完了までお待ちください。');return;}state.uploadBase=state.dataset;state.uploadMode=mode;state.file=null;state.files=[];state.importProgress=[];$('#csv-file').value='';$('#file-label').textContent='CSVファイルを選択、またはドロップ（複数選択可）';$('#import-button').disabled=true;$('#upload-error').hidden=true;$('#upload-progress').hidden=true;$('#csv-after-import').value='analyze';updateUploadMode();openDialog('#upload-dialog');}
function updateUploadMode(preserveMerge=false){const citation=state.uploadMode==='citations',limits=state.status?.limits||{},store=$('#csv-after-import')?.value==='save',mergeChecked=$('#csv-merge-current')?.checked;$$('[data-upload-mode]').forEach(b=>b.classList.toggle('active',b.dataset.uploadMode===state.uploadMode));$('#upload-description').textContent=citation?`現在のデータセット「${state.dataset?.name||'未選択'}」に、論文ごとの年別新規引用数を追加します。`:'Scopus CSVを分割して読み込み、同じ論文を照合しながら最大200,000件まで蓄積できます。複数ファイルは順番に1つのデータセットへ結合します。';$('#upload-help').textContent=citation?'形式：EID、Year、Citations（またはDOIで論文を照合）。Citationsには、その年に新しく受けた引用数を指定してください。累積引用と同じデータベースから取得した年別値を使用します。':'推奨項目：Title、Year、Authors、Abstract、Author Keywords、Cited by、EID、DOI。各CSVは20,000行以内に分割してください。読み込み後にまとめて分析できます。';$('#upload-limits').textContent=`${Number.isFinite(limits.max_upload_bytes)&&limits.max_upload_bytes>0?`1ファイル最大 ${num(Math.floor(limits.max_upload_bytes/1024/1024))} MB`:'ファイル容量の固定上限なし'} / ${num(limits.max_import_rows||20000)}行 · 蓄積上限 ${num(limits.max_dataset_papers||200000)}論文`;$('#import-button').textContent=store?'読み込んで保存':citation?'引用履歴を追加して分析':'読み込んで分析';$('#csv-provider-field').hidden=citation;$('#csv-merge-choice').hidden=citation;$('#csv-file').multiple=!citation;if(citation&&state.files?.length>1){state.files=state.files.slice(0,1);state.file=state.files[0];$('#file-label').textContent=state.file.name;}if(!citation){$('#csv-merge-choice').innerHTML=mergeChoice('csv-merge-current',state.uploadBase);if(preserveMerge&&$('#csv-merge-current'))$('#csv-merge-current').checked=Boolean(mergeChecked);}}
function selectFile(file){return selectFiles(file?[file]:[]);}
function selectFiles(input){if(state.importBusy)return;const files=Array.from(input||[]),maxBytes=state.status?.limits?.max_upload_bytes;state.file=null;state.files=[];state.importProgress=[];$('#import-button').disabled=true;$('#upload-progress').hidden=true;$('#upload-error').hidden=true;if(!files.length)return;if(state.uploadMode==='citations'&&files.length>1){$('#upload-error').textContent='引用履歴は1ファイルずつ追加してください。';$('#upload-error').hidden=false;return;}for(const file of files){if(!file.name.toLowerCase().endsWith('.csv')){$('#upload-error').textContent=`${file.name}：CSV形式のファイルを選択してください。`;$('#upload-error').hidden=false;return;}if(Number.isFinite(maxBytes)&&maxBytes>0&&file.size>maxBytes){$('#upload-error').textContent=`${file.name}：1ファイルの上限は${Math.floor(maxBytes/1024/1024)} MBです。`;$('#upload-error').hidden=false;return;}}state.files=files;state.file=files[0];$('#file-label').textContent=files.length===1?`${files[0].name} · ${(files[0].size/1024/1024).toFixed(1)} MB`:`${num(files.length)}ファイルを順番に結合 · ${(files.reduce((sum,file)=>sum+file.size,0)/1024/1024).toFixed(1)} MB`;if(files.length>1)$('#csv-after-import').value='save';$('#import-button').disabled=false;updateUploadMode(true);}
function renderImportProgress(stage=''){const el=$('#upload-progress');if(!el)return;const rows=state.importProgress||[];el.hidden=!stage&&!rows.length;el.innerHTML=`${stage?`<p role="status">${e(stage)}</p>`:''}${rows.length?`<ol>${rows.map(row=>`<li><strong>${e(row.name)}</strong><span>保存済み ${num(row.total)}論文 · 重複統合 ${num(row.duplicates)}件${row.invalid?` · 無効行 ${num(row.invalid)}件`:''}</span></li>`).join('')}</ol>`:''}`;}
function showStoredDataset(){++state.run;clearRestoreLink();resetFieldReport();resetAuthorNetwork();state.result=null;state.insight=null;state.insightBusy=false;state.view='overview';window.dispatchEvent(new CustomEvent('atlas:result',{detail:null}));$('#analysis-time').textContent='保存済み・未分析';$('#embedding-label').textContent='READY TO ANALYZE';$('#notice').hidden=true;$('#source-notice').hidden=true;$('#period-label').textContent=`${$('#start-year').value} — ${$('#end-year').value}`;$('#content').innerHTML=empty(`${num(state.dataset.paper_count)}件の論文を保存しました`,'CSVを追加して蓄積を続けるか、対象年と分析手法を設定して全体を分析できます。',`<button class="button button-primary" data-action="csv-upload">CSVをさらに追加</button> <button class="button button-quiet" data-action="settings">分析期間・手法を設定</button> <button class="button button-primary" data-action="analyze">保存した論文を分析</button>`);}
function setImportBusy(busy){state.importBusy=busy;$$('#upload-dialog input,#upload-dialog select,#upload-dialog [data-upload-mode],#upload-dialog [data-close]').forEach(el=>el.disabled=busy);$('#import-button').disabled=busy||!state.file;}
async function importFile(){if(!state.file||state.importBusy)return;const files=state.files?.length?[...state.files]:[state.file],selection=++state.selectionVersion,button=$('#import-button'),base=state.uploadBase,mode=state.uploadMode,merge=mode==='papers'&&$('#csv-merge-current')?.checked,provider=$('#csv-provider').value,store=$('#csv-after-import')?.value==='save';let current=merge||mode==='citations'?base:null,completed=0;state.importProgress=[];setImportBusy(true);$('#upload-error').hidden=true;try{if(mode==='citations'&&!base)throw new Error('引用履歴を追加する論文データセットを先に選択してください。');for(const [index,file] of files.entries()){button.textContent=`${index+1} / ${files.length} ファイルを検証中…`;if(typeof renderImportProgress==='function')renderImportProgress(`${index+1} / ${files.length}：${file.name||'CSV'}を読み込んでいます。`);const data=new FormData();data.append('file',file);if(mode==='papers')data.append('provider',provider);const url=mode==='citations'?`/api/datasets/${encodeURIComponent(current.id)}/citations`:'/api/import';let imported=await api(url,{method:'POST',body:data});let duplicates=Number(imported.report?.duplicates_removed||0),invalid=Number(imported.report?.invalid_rows||0);if(current&&mode==='papers'){if(Boolean(current.is_demo)!==Boolean(imported.dataset.is_demo))throw new Error('合成・テストデータと実際の論文データは結合できません。取得元を確認し、別々のデータセットとして保存してください。');button.textContent=`${index+1} / ${files.length} 重複を照合して結合中…`;if(typeof renderImportProgress==='function')renderImportProgress(`${index+1} / ${files.length}：${num(current.paper_count)}件の保存済み論文と重複を照合して保存中です。件数・抄録量によって数分かかることがあります。`);imported=await post('/api/datasets/merge',{base_dataset_id:current.id,additional_dataset_id:imported.dataset.id});duplicates+=Number(imported.report?.duplicates_removed||0);state.reportCache.set(imported.dataset.id,reportsForDataset(current.id));}else if(mode==='citations')state.reportCache.set(imported.dataset.id,reportsForDataset(current.id));current=imported.dataset;completed++;state.importProgress.push({name:file.name||'CSV',total:current.paper_count,duplicates,invalid});if(typeof renderImportProgress==='function')renderImportProgress();if(selection===state.selectionVersion){state.dataset=current;if(mode==='papers')applyDatasetAnalysisDefaults(current);updateDataset();}}await refreshStatus();if(selection!==state.selectionVersion){message('CSVの取込が完了しました。保存済みデータから開けます。');return;}state.files=[];state.file=null;state.uploadBase=current;closeDialogs();message(`${num(current.paper_count)}件の論文を保存しました。${files.length>1||merge?'重複を照合して結合しました。':''}`);if(store)showStoredDataset();else await runAnalysis();}catch(error){if(completed&&selection===state.selectionVersion){state.dataset=current;state.uploadBase=current;state.files=files.slice(completed);state.file=state.files[0]||null;showStoredDataset();}$('#upload-error').textContent=`${completed?`${completed} / ${files.length}ファイル、${num(current.paper_count)}論文は保存済みです。残りのファイルから再試行できます。 `:''}${error.message}`;$('#upload-error').hidden=false;if(typeof renderImportProgress==='function')renderImportProgress('取り込みを停止しました。保存できたデータは保持されています。');if(!$('#upload-dialog').open)message($('#upload-error').textContent,true);}finally{setImportBusy(false);updateUploadMode(true);if(completed<files.length&&completed&&$('#csv-merge-current'))$('#csv-merge-current').checked=true;}}
function safeHTTP(value){try{const url=new URL(String(value||''));return (url.protocol==='https:'||url.protocol==='http:')&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function providerLabel(value){const names={europepmc:'Europe PMC',arxiv:'arXiv',crossref:'Crossref',scopus_csv:'Scopus CSV',scopus:'Scopus',csv:'論文CSV',demo:'合成デモ'};return names[String(value)]||String(value||'取得元未記録');}
function paperProviders(p){const values=Array.isArray(p.providers)?p.providers:typeof p.providers==='string'?[p.providers]:p.provider?[p.provider]:[];return values.length?values.map(providerLabel):[state.result?.meta.is_demo?'合成デモ':'CSV / 取得元未記録'];}
function citationOrigin(p){return p.citation_source?providerLabel(p.citation_source):p.citations==null?'未取得':'計数元未記録';}
function provenanceHTML(p){const url=safeHTTP(p.external_url);return `<div class="source-provenance"><div><span>書誌情報の取得元</span><strong>${e(paperProviders(p).join(' · '))}</strong></div><div><span>被引用数の計数元</span><strong>${e(citationOrigin(p))}${p.citations!=null?` · ${num(p.citations)}件（取得時点）`:''}</strong></div>${url?`<div><span>元の論文・レコード</span><a class="doi-link" href="${e(url)}" target="_blank" rel="noopener noreferrer">取得元の論文を開く ${icon('external')}</a></div>`:''}</div>`;}
function citationSnapshotsHTML(p){const snapshots=Array.isArray(p.citation_snapshots)?p.citation_snapshots:[];if(!snapshots.length)return '';return `<div class="citation-snapshots"><details><summary>取得元ごとの被引用数を確認 <span>${snapshots.length} RECORDS</span></summary><p class="field-help">表示中の集計元：${e(citationOrigin(p))}。データベースごとの収録範囲が異なるため、これらの値は合算しません。</p><div class="table-wrap"><table><thead><tr><th>計数元</th><th class="num">被引用数</th><th>取得日</th></tr></thead><tbody>${snapshots.map(snapshot=>{const retrieved=snapshot.retrieved_at?new Date(snapshot.retrieved_at):null;const date=retrieved&&!Number.isNaN(retrieved.getTime())?retrieved.toLocaleDateString('ja-JP'):'—';return `<tr><td>${e(providerLabel(snapshot.provider))}</td><td class="num">${num(snapshot.count)}</td><td>${e(date)}</td></tr>`;}).join('')}</tbody></table></div></details></div>`;}
function reportsForDataset(id){if(!id)return [];if(state.result?.dataset_id===id&&Array.isArray(state.result?.meta?.source_reports))return state.result.meta.source_reports;return state.reportCache.get(id)||[];}
function currentSourceReports(){const reports=state.result?.meta?.source_reports;return Array.isArray(reports)?reports:reportsForDataset(state.dataset?.id);}
function isSampled(){return Boolean(state.result?.meta?.sampled||currentSourceReports().some(r=>r.truncated));}
function renderSourceNotice(){const el=$('#source-notice'),reports=currentSourceReports();if(!state.result||!reports.length){el.hidden=true;return;}const sampled=isSampled(),names=[...new Set(reports.map(r=>providerLabel(r.provider)))].join(' · ');el.hidden=false;el.classList.toggle('sampled',sampled);el.innerHTML=`${icon(sampled?'warning':'globe')}<div><strong>${sampled?'取得標本内の分析：検索結果全体の成長ではありません。':'公開論文から取得した集合を分析しています。'}</strong><p>${sampled?'年・月ごとの関連度上位を取得枠に沿って抽出しています。件数の増減・予測は検索全体の成長を示しません。':'検索語・提供元の収録範囲・抄録の欠測に左右されます。公開サイト全体を網羅した分析ではありません。'} ${e(names)}</p></div><button data-action="source-report">取得範囲を確認 ↗</button>`;}
function mergeChoice(id,base){if(!base)return '<div class="merge-unavailable">新しいデータセットとして保存します。複数CSVは1つのデータセットへ順に追加します。</div>';if(base.is_demo)return '<div class="merge-unavailable">現在は合成・テストデータを表示しています。読み込んだ論文は、新しいデータセットとして保存します。</div>';return `<label class="merge-choice"><input type="checkbox" id="${e(id)}" ${id==='csv-merge-current'?'checked':''}><span><strong>現在の「${e(base.name)}」に追加する</strong><small>${num(base.paper_count)}件の既存論文とDOI・識別子を照合して結合します。既存の引用値を優先し、取得元ごとの値を保存します。チェックしない場合は新規データセットとして保存します。</small></span></label>`;}
async function showSourceHub(){openDialog('#source-dialog');if(!state.discoverBusy&&!state.discovered){$('#discover-start').value=$('#start-year').value;$('#discover-end').value=$('#end-year').value;}setSourceTab('public');setDiscoveryMode(state.discoverMode);try{if(!state.providers.length){const sources=await api('/api/sources');state.providers=Array.isArray(sources.providers)?sources.providers:[];$('#source-provider').innerHTML=state.providers.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')||'<option value="">利用できる取得元がありません</option>';renderProviderDescription();}}catch(error){$('#discover-error').textContent=error.message;$('#discover-error').hidden=false;}}
function setSourceTab(tab){state.sourceTab=tab;$$('[data-source-tab]').forEach(b=>{const selected=b.dataset.sourceTab===tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));});['public','csv','saved'].forEach(name=>$(`#source-${name}`).hidden=name!==tab);if(tab==='saved')loadSourceDatasets();}
function renderProviderDescription(){const provider=state.providers.find(p=>p.id===$('#source-provider').value);if(!provider){$('#provider-description').textContent='検索先を選択してください。';return;}const limitations=Array.isArray(provider.limitations)?provider.limitations.join(' '):provider.limitations||'';const docs=safeHTTP(provider.docs_url);$('#provider-description').innerHTML=`<strong>${e(provider.name)} <span class="source-filter-pill">APIキー不要</span></strong><p>${e(provider.description)}</p>${limitations?`<p class="provider-limit">${e(limitations)}</p>`:''}${docs?`<a href="${e(docs)}" target="_blank" rel="noopener noreferrer">検索先のデータ仕様 ↗</a>`:''}`;}
async function loadSourceDatasets(){const el=$('#source-dataset-list');el.innerHTML='<p class="muted">保存済みデータを読み込んでいます…</p>';try{await refreshStatus();el.innerHTML=state.status.datasets.map(datasetCardHTML).join('')||empty('保存済みデータはまだありません','公開検索またはCSVから分析を始められます。');}catch(error){el.innerHTML=`<p class="inline-error">${e(error.message)}</p>`;}}
function sourceReportHTML(report,dataset=null){const monthly=Array.isArray(report.month_coverage)&&report.month_coverage.length>0,periods=monthly?report.month_coverage:Array.isArray(report.year_coverage)?report.year_coverage:[];const knownTotals=periods.filter(row=>row.total!=null&&Number.isFinite(Number(row.total)));const total=knownTotals.length===periods.length&&periods.length?knownTotals.reduce((sum,row)=>sum+Number(row.total),0):report.total_results??null;const imported=report.imported_count??dataset?.paper_count,coverage=report.abstract_coverage,periodWord=monthly?'月':'年',deduplicated=Number(report.duplicates_removed)>0;return `<div class="source-report"><div class="source-report-head"><h3>${e(providerLabel(report.provider))} の取得結果</h3><span class="source-pill">${monthly?'MONTHLY · ':''}${report.truncated?'SAMPLED CORPUS':'RETRIEVED CORPUS'}</span></div>${report.query?`<p class="muted">検索語：${e(report.query)}</p>`:''}<div class="source-report-stats"><div class="source-report-stat"><span>検索に一致</span><strong>${num(total)}<small>件</small></strong></div><div class="source-report-stat"><span>${deduplicated?'分析対象（統合後）':'取得した論文'}</span><strong>${num(imported)}<small>件</small></strong></div><div class="source-report-stat"><span>抄録の収録率</span><strong>${percent(coverage)}</strong></div></div><div class="source-report-warning"><strong>${report.truncated?`取得上限に達した${periodWord}があります。検索結果の標本です。`:'検索先の収録範囲内から取得した論文です。'}</strong>${report.truncated?`各${periodWord}の取得枠に配分して、関連度順に抽出しています。標本内の出版数の増減や予測を、検索結果全体の成長として解釈しないでください。`:'検索サイトの収録対象、検索語、取得時点で結果が変わります。全分野・全論文を網羅した集合ではありません。'}${monthly?' 月次比較では、出版月を特定できる論文だけを使用し、当月を除いた完了月どうしを比較します。':''}</div>${periods.length?`<div class="table-wrap source-report-coverage"><table><thead><tr><th>出版${periodWord}</th><th class="num">検索一致件数</th>${monthly?'<th class="num">取得枠</th>':''}<th class="num">${deduplicated?'取得件数（統合前）':'取得件数'}</th><th>取得率</th></tr></thead><tbody>${periods.map(row=>{const ratio=Number(row.total)>0?100*Number(row.imported||0)/Number(row.total):null;return `<tr><td>${e(monthly?row.month:row.year)}</td><td class="num">${num(row.total)}</td>${monthly?`<td class="num">${num(row.allocated)}</td>`:''}<td class="num">${num(row.imported)}</td><td><div style="display:flex;gap:9px;align-items:center"><span class="source-coverage-track"><i style="width:${clamp(ratio||0,0,100)}%"></i></span><span style="font-size:9px;min-width:35px;text-align:right">${ratio==null?'—':ratio>0&&ratio<.1?'&lt;0.1%':`${ratio<1?ratio.toFixed(1):Math.round(ratio)}%`}</span></div></td></tr>`;}).join('')}</tbody></table></div>`:''}${deduplicated?`<p class="field-help">年・月別の取得件数は重複照合前です。DOI・タイトルなどの照合で${num(report.duplicates_removed)}件を統合したため、表の合計と分析対象件数は異なります。</p>`:''}${report.warnings?.length?`<ul class="source-report-notes">${report.warnings.map(w=>`<li>${e(w)}</li>`).join('')}</ul>`:''}</div>`;}
function parseMonth(value){const match=/^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(value||''));if(!match)return null;return {year:Number(match[1]),month:Number(match[2]),index:Number(match[1])*12+Number(match[2])-1};}
function monthFromIndex(index){return `${Math.floor(index/12)}-${String(index%12+1).padStart(2,'0')}`;}
function latestCompleteMonth(){const now=new Date();return monthFromIndex(now.getFullYear()*12+now.getMonth()-1);}
function setDiscoveryMode(mode){if(!['year','month'].includes(mode))return;state.discoverMode=mode;const monthly=mode==='month';if(monthly&&(!$('#discover-start-month').value||!$('#discover-end-month').value)){const end=parseMonth(latestCompleteMonth()).index;$('#discover-start-month').value=monthFromIndex(end-11);$('#discover-end-month').value=monthFromIndex(end);}for(const id of ['discover-start','discover-end']){$('#'+id).disabled=monthly||state.discoverBusy;$('#'+id).required=!monthly;$('#'+id+'-label').hidden=monthly;}for(const id of ['discover-start-month','discover-end-month']){$('#'+id).disabled=!monthly||state.discoverBusy;$('#'+id).required=monthly;$('#'+id).max=latestCompleteMonth();$('#'+id+'-label').hidden=!monthly;}$$('[data-discover-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.discoverMode===mode);b.disabled=state.discoverBusy;});$('[data-action="recent-twelve"]').disabled=state.discoverBusy;$('#discovery-quota-help').textContent=monthly?'APIキー不要 · 各月に取得枠を配分 / 最大24か月':'APIキー不要 · 各年に取得枠を配分';}
function setRecentTwelve(){if(state.discoverBusy)return;const end=parseMonth(latestCompleteMonth()).index;$('#discover-start-month').value=monthFromIndex(end-11);$('#discover-end-month').value=monthFromIndex(end);setDiscoveryMode('month');$('#discover-error').hidden=true;}
function setDiscoveryBusy(busy){state.discoverBusy=busy;['source-provider','discover-query','discover-limit','discover-button'].forEach(id=>$("#"+id).disabled=busy);setDiscoveryMode(state.discoverMode);$('#discover-progress').hidden=!busy;$('#discover-button').innerHTML=busy?'論文を取得しています…':`${icon('search')}公開論文を取得`;}
async function discoverPapers(){if(state.discoverBusy)return;const provider=$('#source-provider').value,query=$('#discover-query').value.trim(),monthly=state.discoverMode==='month',startMonth=$('#discover-start-month').value,endMonth=$('#discover-end-month').value,from=parseMonth(startMonth),to=parseMonth(endMonth),start=monthly?from?.year:Number($('#discover-start').value),end=monthly?to?.year:Number($('#discover-end').value),limit=Number($('#discover-limit').value),errorEl=$('#discover-error');errorEl.hidden=true;if(!state.providers.some(p=>p.id===provider)||query.length<2||query.length>500){errorEl.textContent='検索先を選び、検索語を2〜500文字で入力してください。';errorEl.hidden=false;return;}if(monthly&&(!from||!to||from.index>to.index||to.index-from.index>=24||endMonth>latestCompleteMonth())){errorEl.textContent='月単位の取得は、最新完了月までの最大24か月で指定してください。';errorEl.hidden=false;return;}if(!Number.isInteger(start)||!Number.isInteger(end)||start<1900||end>(Number(state.status?.default_end_year)+1||new Date().getFullYear())||start>end||end-start>=20){errorEl.textContent='検索期間は1900年から当年まで、開始年から20年以内に設定してください。';errorEl.hidden=false;return;}if(!Number.isInteger(limit)||limit<20||limit>1000){errorEl.textContent='最大取得数は20〜1,000件で指定してください。';errorEl.hidden=false;return;}const token=++state.discoverRun,base=state.dataset,payload={provider,query,start_year:start,end_year:end,limit};if(monthly){payload.start_month=startMonth;payload.end_month=endMonth;}state.discovered=null;$('#discover-results').hidden=true;setDiscoveryBusy(true);$('#discover-progress').textContent='公開サイトへ問い合わせています。取得結果はローカルに保存します。';try{const job=await post('/api/discover',payload);while(token===state.discoverRun){const update=await api(`/api/jobs/${encodeURIComponent(job.job_id)}`);if(token!==state.discoverRun)return;if(update.status==='failed')throw new Error(update.error||'公開論文の取得に失敗しました。');if(update.status==='completed'){if(!update.dataset)throw new Error('取得済みデータセットが返されませんでした。');state.discovered={dataset:update.dataset,report:update.report||{},base,start,end,startMonth:monthly?startMonth:null,endMonth:monthly?endMonth:null};state.reportCache.set(update.dataset.id,[update.report||{}]);$('#discover-results').innerHTML=`${sourceReportHTML(update.report||{},update.dataset)}${mergeChoice('discover-merge-current',base)}<div class="source-report-actions"><span>データは保存済み · ${monthly?`${e(startMonth)}–${e(endMonth)} / 月次の比較窓3か月`:`${start}–${end}年`}で分析</span><button class="button button-primary" data-action="use-discovered">取得した論文を分析 ${icon('arrow')}</button></div>`;$('#discover-results').hidden=false;if(!$('#source-dialog').open)message('公開論文の取得が完了しました。「データを追加」から結果を確認できます。');await refreshStatus();return;}$('#discover-progress').textContent=update.stage||`${monthly?'各月':'各年'}の論文を取得しています…`;await new Promise(resolve=>setTimeout(resolve,950));}}catch(error){if(token===state.discoverRun){errorEl.textContent=error.message;errorEl.hidden=false;}}finally{if(token===state.discoverRun)setDiscoveryBusy(false);}}
async function useDiscovered(){const ready=state.discovered;if(!ready)return;const button=$('[data-action="use-discovered"]');if(button.disabled)return;const selection=++state.selectionVersion;button.disabled=true;const merge=$('#discover-merge-current')?.checked;try{let dataset=ready.dataset,reports=[ready.report];if(merge){if(!ready.base||ready.base.is_demo||dataset.is_demo)throw new Error('合成・テストデータと実際の論文データは結合できません。');button.textContent='重複を照合して結合しています…';const combined=await post('/api/datasets/merge',{base_dataset_id:ready.base.id,additional_dataset_id:dataset.id});dataset=combined.dataset;reports=[...reportsForDataset(ready.base.id),ready.report];}state.reportCache.set(dataset.id,reports);if(selection!==state.selectionVersion){message('結合処理が完了しました。保存済みデータから開けます。');return;}state.dataset=dataset;$('#start-year').value=ready.start;$('#end-year').value=ready.end;$('#monthly-anchor').value=ready.endMonth||'';if(ready.endMonth)$('#monthly-window').value='3';updateDataset();closeDialogs();message(`${num(dataset.paper_count)}件の取得論文を分析します。`);await runAnalysis();}catch(error){$('#discover-error').textContent=error.message;$('#discover-error').hidden=false;}finally{if(button.isConnected){button.disabled=false;button.innerHTML=`取得した論文を分析 ${icon('arrow')}`;}}}
function showSourceReport(){const reports=currentSourceReports();$('#detail-eyebrow').textContent='CORPUS COVERAGE & PROVENANCE';$('#detail-title').textContent='どの範囲の論文を分析しているか';$('#detail-body').innerHTML=`<p class="muted">取得条件と年別の検索件数を確認できます。結合後も、元の取得集合の範囲と制約を引き継ぎます。</p>${reports.map(r=>sourceReportHTML(r)).join('')||'<p class="field-help">公開検索の取得記録はありません。</p>'}`;openDialog('#detail-dialog');}
function showExport(){if(!state.result){message('分析完了後にエクスポートできます。');return;}['html','csv','json'].forEach(format=>{$(`#export-${format}`).href=`/api/results/${encodeURIComponent(state.result.id)}/export?format=${format}`;});openDialog('#export-dialog');}

/* Field reports keep their own request identity; no generated prose changes analytical values. */
const fieldState={request:0,resultId:null,topicId:null,neighborId:null,report:null,busy:false,error:'',stage:'',provider:'none',completed:false,llm:null,llmError:'',localModel:'',chartMode:'line',llmRequest:0};
function resetFieldReport(){++fieldState.request;Object.assign(fieldState,{resultId:null,topicId:null,neighborId:null,report:null,busy:false,error:'',completed:false,provider:'none'});if($('#field-report-dialog').open)$('#field-report-dialog').close();}
function fieldCurrent(){return Boolean(state.result&&fieldState.resultId===state.result.id&&topicFor(fieldState.topicId));}
function fieldEvidenceButton(ids,label='根拠を確認',total=null){const all=Array.isArray(ids)?ids:[],shown=all.slice(0,50),count=Math.max(all.length,Number(total)||0);return shown.length?`<button class="text-link" data-field-evidence="${e(JSON.stringify(shown))}" data-evidence-title="${e(label)}" data-evidence-total="${count}">${e(label)}${count>shown.length?`（${num(shown.length)} / ${num(count)}件）`:''} ${icon('arrow')}</button>`:'';}
function fieldNotes(notes){return Array.isArray(notes)&&notes.length?`<ul class="field-notes">${notes.map(note=>`<li>${e(note)}</li>`).join('')}</ul>`:'';}
function fieldPanel(title,english,body,extra=''){return `<section class="panel field-panel">${panelHeader(title,english,extra)}<div class="field-panel-body">${body}</div></section>`;}
function fieldScopeNotice(report){const sampled=report?.scope?.sampled??isSampled();return `<div class="field-scope ${sampled?'sampled':''}">${icon(sampled?'warning':'info')}<p>${sampled?'取得標本内の分析です。年・月ごとの取得枠に制約されるため、件数の増減・予測は検索結果全体の成長を示しません。':'選択した期間・取得済み論文の範囲で比較します。分野全体の網羅調査ではありません。'}${report?.display_limits?` 根拠IDの一覧は1項目あたり最大${num(report.display_limits.evidence_ids)}件の表示です。各指標は全対象論文から集計し、すべての根拠はCSVに保存しています。`:''}${state.result?.meta.is_demo?' 現在は合成・テストデータを含んでいます。':''}</p></div>`;}
async function openFieldReport(topicId){const topic=topicFor(topicId);if(!topic)return;state.topic=topicId;if(isUnclassified(topic)){state.technologyTab='map';closeDialogs();setView('technology');return;}const reuse=fieldCurrent()&&fieldState.topicId===topicId;fieldState.resultId=state.result.id;fieldState.topicId=topicId;if(!reuse){++fieldState.request;fieldState.report=null;fieldState.neighborId=null;fieldState.error='';fieldState.busy=false;fieldState.completed=false;fieldState.provider='none';fieldState.chartMode='line';}openDialog('#field-report-dialog');renderFieldReport();refreshFieldLLM();if(!reuse||(!fieldState.report&&!fieldState.busy))requestFieldReport('none');}
async function refreshFieldLLM(){const resultId=fieldState.resultId,request=++fieldState.llmRequest;try{const status=await api('/api/llm/status');if(request!==fieldState.llmRequest||fieldState.resultId!==resultId||!fieldCurrent())return;fieldState.llm=status;fieldState.llmError='';const models=status.local?.models||[];if(!fieldState.busy&&!models.some(model=>model.id===fieldState.localModel))fieldState.localModel=models.some(model=>model.id===status.local?.default_model)?status.local.default_model:models[0]?.id||status.local?.default_model||'';}catch(error){if(request!==fieldState.llmRequest||fieldState.resultId!==resultId)return;fieldState.llmError=error.message;fieldState.llm=null;}if($('#field-llm-controls')&&$('#field-report-dialog').open)$('#field-llm-controls').innerHTML=fieldLLMControls();}
function fieldGenerationFeedback(){const busy=fieldState.busy,error=fieldState.error,done=fieldState.completed;if(!busy&&!error&&!done)return '';const text=busy?fieldState.stage:error||'解釈を更新しました。下に生成結果を表示しています。';return `<div class="field-generation-feedback ${error?'is-error':done&&!busy?'is-complete':''}" role="${error?'alert':'status'}" aria-live="${error?'assertive':'polite'}"><span ${busy?'data-field-progress':''}>${e(text)}</span>${error?`<button class="text-link" data-action="field-retry">同じ方法で再試行 ${icon('refresh')}</button>`:''}</div>`;}
function refreshFieldGenerationFeedback(){const box=$('#field-generation-feedback');if(box)box.innerHTML=fieldGenerationFeedback();$$('[data-field-progress]').forEach(node=>node.textContent=fieldState.stage);}
async function requestFieldReport(provider='none',neighborId=fieldState.neighborId){
 if(!fieldCurrent()){message('先に分析結果から分野を選択してください。',true);return;}
 if(fieldState.busy&&provider!=='none'){refreshFieldGenerationFeedback();return;}
 const unavailable=provider==='local'&&!fieldState.llm?.local?.available?'ローカルLLMに接続できません。「接続設定」と「接続を再確認」で確認してください。':provider==='openai'&&!fieldState.llm?.openai?.configured?'OpenAIの接続設定がありません。APIキーとモデルを保存してください。':'';
 if(unavailable){fieldState.provider=provider;fieldState.completed=false;fieldState.error=unavailable;refreshFieldGenerationFeedback();return;}
 const resultId=fieldState.resultId,topicId=fieldState.topicId,request=++fieldState.request,model=provider==='local'?fieldState.localModel||null:null;
 const sameComparison=fieldState.report&&fieldState.report.focus?.id===topicId&&(fieldState.report.neighbor?.id||null)===(neighborId||null);
 if(!sameComparison)fieldState.report=null;
 Object.assign(fieldState,{neighborId:neighborId||null,busy:true,error:'',completed:false,provider});
 fieldState.stage=provider==='none'?'分野・隣接領域の計測結果をまとめています…':provider==='local'?'ローカルLLMが、数値と根拠をもとに解釈しています…':'OpenAIが、選択された根拠をもとに解釈しています…';
 renderFieldReport();
 const current=()=>request===fieldState.request&&state.result?.id===resultId&&fieldState.topicId===topicId;
 try{
  const created=await post('/api/field-reports',{result_id:resultId,topic_id:topicId,neighbor_id:neighborId||null,provider,model});
  if(!current())return;
  if(!created.job_id)throw new Error('生成処理の識別子が返りませんでした。再試行してください。');
  while(current()){
   const job=await api(`/api/jobs/${encodeURIComponent(created.job_id)}`);
   if(!current())return;
   if(job.status==='failed'){
    if(job.field_report_id&&!fieldState.report){try{const fallback=await api(`/api/field-reports/${encodeURIComponent(job.field_report_id)}`);if(!current())return;if(fallback.result_id===resultId&&fallback.focus?.id===topicId){fieldState.report=fallback;fieldState.neighborId=fallback.neighbor?.id||null;}}catch{if(!current())return;}}
    throw new Error(job.error||'総合分析を生成できませんでした。');
   }
   if(job.status==='completed'){
    if(!job.field_report_id)throw new Error('総合分析の識別子が返りませんでした。');
    const report=await api(`/api/field-reports/${encodeURIComponent(job.field_report_id)}`);
    if(!current())return;
    if(report.result_id!==resultId||report.focus?.id!==topicId)throw new Error('別の分析結果が返されたため表示を中止しました。');
    fieldState.report=report;fieldState.neighborId=report.neighbor?.id||null;fieldState.completed=provider!=='none';break;
   }
   fieldState.stage=job.stage||fieldState.stage;
   refreshFieldGenerationFeedback();
   await new Promise(resolve=>setTimeout(resolve,850));
  }
 }catch(error){if(current())fieldState.error=error.message;}
 finally{if(current()){fieldState.busy=false;if($('#field-report-dialog').open)renderFieldReport();}}
}
function fieldLLMControls(){const status=fieldState.llm,local=status?.local,openai=status?.openai,models=local?.models||[],busy=fieldState.busy;return `<div class="field-llm-options" aria-busy="${busy?'true':'false'}"><div><span class="field-option-title">${icon('database')}ローカルLLM</span><p>サーバーのローカルモデルに数値と抄録抜粋を渡して解釈します。</p><label class="sr-only" for="field-local-model">ローカルLLMモデル</label><select id="field-local-model" ${!local?.available||busy?'disabled':''}>${models.length?models.map(model=>`<option value="${e(model.id)}" ${model.id===fieldState.localModel?'selected':''}>${e(model.id)}</option>`).join(''):`<option value="${e(fieldState.localModel)}">${e(fieldState.localModel||'モデル未接続')}</option>`}</select><button class="button button-quiet button-small" data-field-provider="local" ${!local?.available||busy?'disabled':''}>${icon('sparkles')}${busy&&fieldState.provider==='local'?'解釈を生成中…':'ローカルLLMで解釈'}</button><small>${local?.available?e(local.backend||'ローカル接続'):`未接続${local?.error?` · ${e(local.error)}`:''}`}</small></div><div><span class="field-option-title">${icon('globe')}OpenAI</span><p>このボタンを押すと、比較指標・論文タイトル・著者名・所属・抄録抜粋をOpenAI APIへ送信します。</p><span class="field-model-label">${e(openai?.model||'モデル未設定')}</span><button class="button button-quiet button-small" data-field-provider="openai" ${!openai?.configured||busy?'disabled':''}>${icon('sparkles')}${busy&&fieldState.provider==='openai'?'解釈を生成中…':'OpenAIで解釈'}</button><small>${openai?.configured?'設定あり · 明示操作時のみ外部送信':'未設定 · ブラウザの接続設定でAPIキーとモデルを入力'}</small></div></div>${!local?.available?'<p class="field-help">ローカルLLMはブラウザの接続設定で方式・URL・モデルを指定します。Ollama、または LM Studio（openai_compatible）などのローカル接続に対応します。</p>':''}${fieldState.llmError?`<p class="field-help">接続状態を取得できませんでした：${e(fieldState.llmError)}</p>`:''}<div id="field-generation-feedback">${fieldGenerationFeedback()}</div><div class="field-llm-foot"><span>LLMの文章は仮説の補助です。数値・時系列予測は書き換えません。</span><button class="text-link" data-connection-open>接続設定</button><button class="text-link" data-action="field-llm-refresh">接続を再確認 ${icon('refresh')}</button></div>`;}
function fieldComparisonChart(report){const annual=report.annual||[],focus=report.focus,neighbor=report.neighbor;if(!annual.length)return '<p class="field-empty">年別の件数を比較できるデータがありません。</p>';const years=annual.map(row=>Number(row.year));const series=[{label:focus.label,color:'#58e0c5',values:annual.map(row=>({year:Number(row.year),value:row.focus_count}))}];if(neighbor)series.push({label:neighbor.label,color:'#77a8fc',values:annual.map(row=>({year:Number(row.year),value:row.neighbor_count}))});let chart;if(fieldState.chartMode==='bar'){const max=Math.max(1,...annual.flatMap(row=>[Number(row.focus_count)||0,Number(row.neighbor_count)||0])),w=720,h=230,left=44,right=20,top=23,bottom=35,pw=w-left-right,ph=h-top-bottom,step=pw/Math.max(1,annual.length),bw=Math.min(29,step*.29);chart=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="選択分野と隣接分野の年別論文数"><text class="chart-axis" x="${left}" y="12">論文数</text>${[0,.5,1].map(part=>`<line class="chart-grid" x1="${left}" y1="${top+ph*(1-part)}" x2="${w-right}" y2="${top+ph*(1-part)}"/><text class="chart-axis" x="${left-8}" y="${top+ph*(1-part)+4}" text-anchor="end">${num(max*part)}</text>`).join('')}${annual.map((row,i)=>{const x=left+step*(i+.5);return `${[row.focus_count,...(neighbor?[row.neighbor_count]:[])].map((value,j)=>{if(value==null)return '';const bh=ph*Number(value)/max,xx=x+(neighbor?(j===0?-bw-2:2):-bw/2);return `<rect x="${xx}" y="${top+ph-bh}" width="${bw}" height="${Math.max(0,bh)}" rx="2" fill="${j?'#77a8fc':'#58e0c5'}" opacity=".8"><title>${e(row.year)} · ${e(j?neighbor.label:focus.label)}：${num(value)}論文</title></rect>`;}).join('')}<text class="chart-axis" x="${x}" y="${h-11}" text-anchor="middle">${e(row.year)}</text>`;}).join('')}</svg>`;}else chart=makeLineChart(series,years,{height:230});return `<div class="field-chart-legend"><span><i style="background:#58e0c5"></i>${e(focus.label)}</span>${neighbor?`<span><i style="background:#77a8fc"></i>${e(neighbor.label)}</span>`:''}</div><div class="field-chart">${chart}</div><details class="field-table-details"><summary>年別の実数を確認</summary><div class="table-wrap"><table><thead><tr><th>出版年</th><th class="num">選択分野</th>${neighbor?'<th class="num">隣接分野</th>':''}</tr></thead><tbody>${annual.map(row=>`<tr><td>${e(row.year)}</td><td class="num">${num(row.focus_count)}</td>${neighbor?`<td class="num">${num(row.neighbor_count)}</td>`:''}</tr>`).join('')}</tbody></table></div></details>`;}
function fieldFlow(report){const connections=report.connections||{},counts=connections.transition_counts||{},transitions=connections.transitions||[],shared=connections.shared_authors||[];const labels={focus_to_neighbor:'選択分野 → 隣接分野',neighbor_to_focus:'隣接分野 → 選択分野',same_year:'両分野で同年に初出'};if(!report.neighbor)return '<p class="field-empty">比較可能な隣接分野がないため、分野間の観測順序は集計していません。</p>';const directions=['focus_to_neighbor','neighbor_to_focus','same_year'];return `<p class="field-reading-note">取得期間内の著者の初出年を比較した観測順序です。研究者の移籍・因果的な影響・研究開始年を表すものではありません。</p><div class="field-flow">${directions.map((direction,i)=>`<div class="field-flow-lane"><span>${e(i===1?'隣接分野':i===2?'選択分野':'選択分野')}</span><div><svg viewBox="0 0 210 45" aria-hidden="true"><path d="M5 23C55 ${i===2?23:4} 155 ${i===2?23:42} 201 23" fill="none" stroke="${i===1?'#77a8fc':i===2?'#8d9fb7':'#58e0c5'}" stroke-width="${Math.min(10,2+Math.sqrt(Number(counts[direction])||0))}" opacity=".4"/>${i===2?'<path d="M7 17v12M202 17v12" stroke="#8d9fb7"/>':'<path d="m194 16 9 7-9 7" fill="none" stroke="#7ea6b2"/>'}</svg><strong>${num(counts[direction])}<small>著者</small></strong></div><span>${i===1?'選択分野':i===2?'同年 · 隣接分野':'隣接分野'}</span></div>`).join('')}</div><div class="field-flow-meta">両分野で観測された著者 <strong>${num(connections.shared_authors_total??shared.length)}</strong> 名</div>${transitions.length?`<details class="field-table-details"><summary>著者ごとの初出年と根拠（全${num(connections.transitions_total??transitions.length)}件中${num(transitions.length)}件）</summary><div class="table-wrap"><table><thead><tr><th>著者</th><th>観測順序</th><th>初出年</th><th>照合方法 / 根拠</th></tr></thead><tbody>${transitions.map(row=>`<tr><td>${fieldEvidenceButton(row.evidence_ids,row.name||row.author_id,row.evidence_ids_total??row.evidence_total)}</td><td>${e(labels[row.direction]||row.direction)}</td><td>${e(row.from_year)} → ${e(row.to_year)}</td><td><small>${e(({orcid:'ORCID',scopus_id:'Scopus著者ID',provided_id:'提供された著者ID',name_alias_estimate:'名前の別表記による推定',name_estimate:'著者名による推定'})[row.identity_basis]||row.identity_basis||'未記録')}</small>${fieldEvidenceButton(row.evidence_ids,'著者の根拠',row.evidence_ids_total??row.evidence_total)}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="field-empty">両分野で初出年を比較できる著者がありません。</p>'}${fieldNotes(connections.basis_notes)}`;}
function fieldComparisonTable(section,kind,hasNeighbor){const rows=section?.rows||[],isInstitution=kind==='institutions',label=isInstitution?'所属機関':'手法の言及',max=Math.max(1,...rows.flatMap(row=>[Number(row.focus_count)||0,Number(row.neighbor_count)||0]));return `<div class="field-chart-legend"><span><i style="background:#58e0c5"></i>選択分野</span>${hasNeighbor?'<span><i style="background:#77a8fc"></i>隣接分野</span>':''}</div>${isInstitution?`<div class="field-coverage"><span>所属情報のある論文</span><strong>選択 ${percent(section?.focus_coverage_pct)}${hasNeighbor?` / 隣接 ${percent(section?.neighbor_coverage_pct)}`:''}</strong></div>`:'<p class="field-reading-note">抄録に手法名が言及された論文数です。実際に採用された手法とは限りません。</p>'}${rows.length?`<div class="field-comparison-rows">${rows.slice(0,14).map(row=>`<div class="field-comparison-row"><div><strong>${e(row.name)}</strong>${fieldEvidenceButton(row.evidence_ids,'根拠',row.evidence_ids_total??row.evidence_total)}</div><div class="field-double-bars"><span><i style="width:${clamp(100*Number(row.focus_count)/max,0,100)}%"></i><b>${num(row.focus_count)}</b></span>${hasNeighbor?`<span class="neighbor"><i style="width:${clamp(100*Number(row.neighbor_count)/max,0,100)}%"></i><b>${num(row.neighbor_count)}</b></span>`:''}</div></div>`).join('')}</div><p class="field-help">${e(label)} · 上位${Math.min(rows.length,14)}件を表示。数値は論文単位で集計。${isInstitution?'複数所属を持つ論文は複数行に含まれます。':''}</p>`:`<p class="field-empty">${isInstitution?'比較できる所属情報がありません。所属を含むCSVで補完できます。':'辞書に一致する手法の言及を検出できませんでした。手法が使われていないことを意味しません。'}</p>`}${fieldNotes(section?.notes)}`;}
function fieldKeywords(report){const words=report.keywords||{},groups=[['shared','共通する語','COMMON GROUND'],['focus_only','選択分野に特徴的な語','FOCUS'],['neighbor_only','隣接分野に特徴的な語','NEIGHBOR']];return `<div class="field-keyword-grid">${groups.filter(([key])=>report.neighbor||key!=='neighbor_only').map(([key,label,english])=>`<div><span class="eyebrow">${english}</span><h4>${label}</h4><div class="tags">${(words[key]||[]).slice(0,16).map(word=>`<span class="tag">${e(word)}</span>`).join('')||'<span class="field-help">該当する語はありません</span>'}</div></div>`).join('')}</div><p class="field-help">語の有無は抽出条件と表記に依存します。研究内容に共通点がないことを示すものではありません。</p>`;}
function fieldForecast(report){const topic=report.focus,actual=(topic.series||[]).map(row=>({year:Number(row.year),value:row.count})),future=topic.forecast||[],bt=topic.backtest||{};if(!future.length)return '<p class="field-empty">この分野の予測シナリオはありません。短い期間・少ない観測など、分析条件を確認してください。</p>';const last=actual.at(-1),years=[...new Set([...actual.map(row=>row.year),...future.map(row=>Number(row.year))])].sort((a,b)=>a-b),band=[...(last?[{...last,lower:last.value,upper:last.value}]:[]),...future],lines=[{label:'観測論文数',color:'#58e0c5',values:actual},{label:'予測シナリオ',color:'#77a8fc',dashed:true,values:[...(last?[last]:[]),...future]}];return `<div class="field-chart-legend"><span><i style="background:#58e0c5"></i>観測論文数</span><span><i style="background:#77a8fc"></i>予測シナリオ / 不確実性の幅</span></div><div class="field-chart">${makeLineChart(lines,years,{height:230,forecastStart:last?.year,band})}</div><div class="field-validation"><span>モデルMAE <strong>${bt.mae==null?'—':Number(bt.mae).toFixed(1)}</strong></span><span>ベースラインMAE <strong>${bt.baseline_mae==null?'—':Number(bt.baseline_mae).toFixed(1)}</strong></span><span>検証点 <strong>${num(bt.folds)}</strong></span></div><p class="field-reading-note">既存の出版数予測を表示しています。技術の成功確率や実用化時期の予測ではありません。全期間でテーマを抽出しているため、検証は完全な前向き評価ではありません。</p>`;}
function fieldNarrative(report){const narrative=report.narrative||{},mode={deterministic:'数値から整理 · LLM未使用',local_llm:'ローカルLLMによる解釈',openai:'OpenAIによる解釈'}[narrative.mode]||'数値から整理',sections=narrative.sections?.length?narrative.sections:(report.observations||[]);return `<div class="field-narrative-meta"><span class="source-pill">${e(mode)}</span>${narrative.model?`<small>${e(narrative.model)}</small>`:''}<button class="text-link" data-field-provider="none" ${fieldState.busy?'disabled':''}>数値ベースに戻す ${icon('refresh')}</button></div><h3 class="field-narrative-headline">${e(narrative.headline||'計測結果と根拠から、この分野を読み解く')}</h3>${sections.length?sections.map((section,i)=>`<article class="field-narrative-section"><span>${String(i+1).padStart(2,'0')}</span><div><h4>${e(section.title||section.section||'観測結果')}</h4><p>${e(section.text||'')}</p>${fieldEvidenceButton(section.evidence_ids,'この記述の根拠')}</div></article>`).join(''):'<p class="field-empty">生成文章はまだありません。各数値・根拠論文から確認できます。</p>'}${fieldNotes(narrative.caveats)}`;}
function fieldConnectionsEvidence(report){const connections=report.connections||{},bridges=connections.bridge_papers||[],links=connections.citation_links||[];return `<div class="field-connection-summary"><div><span>両分野に関連する論文</span><strong>${num(connections.bridge_papers_total??bridges.length)}</strong></div><div><span>確認できた分野間引用リンク</span><strong>${connections.citation_coverage?.available===false?'—':num(connections.citation_links_total??links.length)}</strong></div></div>${bridges.length?evidenceList(bridges.map(p=>p.id),5):'<p class="field-help">両分野をつなぐ根拠論文は検出されていません。</p>'}${links.length?`<details class="field-table-details"><summary>取得済みの引用リンク</summary><div class="field-citation-links">${links.slice(0,20).map(link=>`<div><button class="text-link" data-paper="${e(link.source_id)}">${e(state.result.papers.find(p=>p.id===link.source_id)?.title||link.source_id)}</button><span>引用 →</span><button class="text-link" data-paper="${e(link.target_id)}">${e(state.result.papers.find(p=>p.id===link.target_id)?.title||link.target_id)}</button></div>`).join('')}</div></details>`:''}${connections.citation_coverage?`<div class="field-coverage"><span>参照リストの取得率</span><strong>${percent(connections.citation_coverage.coverage_pct)} · ${num(connections.citation_coverage.papers_with_references)} / ${num(connections.citation_coverage.papers_total)}論文</strong></div>`:''}<p class="field-reading-note">引用関係は取得できた参照情報だけから表示します。累積被引用数やマップの近さから引用リンクを推測しません。0件でも引用関係が存在しないとは言えません。</p>`;}
function renderFieldReport(){if(!fieldCurrent())return;const report=fieldState.report,focus=report?.focus||topicFor(fieldState.topicId);$('#field-report-title').textContent=`${focus.label} · 総合分析`;const progress=fieldState.busy?`<div class="discover-progress field-report-progress" role="status" id="field-report-progress" data-field-progress>${e(fieldState.stage)}</div>`:'';const error=fieldState.error?`<div class="inline-error field-report-error" role="alert">${e(fieldState.error)}${report?'<p>取得できた同じ分野比較のレポートを表示しています。生成モードを確認してください。</p>':'<p>既存の分析結果は保持されています。</p>'}<button class="text-link" data-action="field-retry">再試行 ${icon('refresh')}</button></div>`:'';if(!report){$('#field-report-body').innerHTML=`<div class="field-report-loading"><span class="eyebrow">READING THE CONNECTIONS</span><h3>${e(focus.label)}</h3><p>出版動向、隣接分野との著者・所属・手法のつながりをまとめます。</p>${progress}${error}${!fieldState.busy?`<button class="button button-quiet" data-action="field-legacy">既存の分野詳細を表示 ${icon('arrow')}</button>`:'<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>'}</div>`;return;}const neighbor=report.neighbor,neighbors=report.neighbors||focus.neighbors||[],canCompare=neighbors.length>0,shared=report.connections?.shared_authors||[];$('#field-report-body').innerHTML=`<div class="field-report-toolbar"><div><span class="source-pill">${e(topicModelName(report.topic_model))}</span><span>${e(state.result.meta.start_year)} — ${e(state.result.meta.end_year)} · ${state.result.meta.is_demo?'合成・テストデータ':'取得済み論文'}</span></div><div class="field-export-actions">${state.result.meta.topic_model==='nmf'?`<button class="button button-primary button-small" data-foresight-topic="${e(focus.id)}">${icon('target')}この分野の有望領域を探索</button>`:''}${[['data','分析データ'],['report','レポート'],['papers','根拠論文']].map(([kind,label])=>`<a class="button button-quiet button-small" href="/api/field-reports/${encodeURIComponent(report.id)}/export?kind=${kind}" download>${icon('download')}${label} CSV</a>`).join('')}</div></div>${progress}${error}${fieldScopeNotice(report)}<div class="field-focus-hero"><div class="field-focus-title"><span class="eyebrow">SELECTED FIELD</span><h3>${e(focus.label)}</h3><div class="tags">${(focus.keywords||[]).slice(0,7).map(word=>`<span class="tag">${e(word)}</span>`).join('')}</div></div><div class="field-focus-metric"><strong>${num(focus.count)}</strong><span>選択分野の論文</span></div><div class="field-focus-metric neighbor"><strong>${neighbor?num(neighbor.count):'—'}</strong><span>隣接分野の論文</span></div><div class="field-focus-metric"><strong>${num(report.connections?.shared_authors_total??shared.length)}</strong><span>共通する著者</span></div></div><div class="field-neighbor-control"><label for="field-neighbor">比較する隣接分野</label><select id="field-neighbor" ${!canCompare?'disabled':''}>${neighbors.length?`${!neighbor?'<option value="" selected disabled>比較先を選択</option>':''}${neighbors.map(item=>`<option value="${e(item.topic_id)}" ${item.topic_id===neighbor?.id?'selected':''}>${e(item.label)}</option>`).join('')}`:'<option value="">比較可能な分野がありません</option>'}</select><span>${neighbor?'文章表現・テーマ分布の近さを手がかりに比較':'単一分野の総合分析を表示しています'}</span></div>${neighbor?`<p class="field-neighbor-note">選択：${e(focus.label)}　/　隣接：${e(neighbor.label)}${(()=>{const relation=neighbors.find(item=>item.topic_id===neighbor.id),method={nmf_centroid_cosine:'NMF重心のcosine類似度',representative_keyword_jaccard:'代表語のJaccard類似度'}[relation?.method]||relation?.method;return method?` · ${e(method)}${Number.isFinite(relation?.similarity)?` ${Number(relation.similarity).toFixed(3)}`:''}`:'';})()}</p>`:''}<div class="field-main-grid">${fieldPanel('出版動向を比較','PUBLICATION TRAJECTORIES',fieldComparisonChart(report),`<div class="segmented"><button data-field-chart="line" class="${fieldState.chartMode==='line'?'active':''}">折線</button><button data-field-chart="bar" class="${fieldState.chartMode==='bar'?'active':''}">棒</button></div>`)}${fieldPanel('著者がつなぐ分野','OBSERVED AUTHOR SEQUENCE',fieldFlow(report))}</div><div class="field-main-grid field-equal-grid">${fieldPanel('所属機関の分布','INSTITUTION COMPARISON',fieldComparisonTable(report.institutions,'institutions',Boolean(neighbor)))}${fieldPanel('手法の言及を比較','METHOD MENTIONS',fieldComparisonTable(report.methods,'methods',Boolean(neighbor)))}</div>${fieldPanel('共通点と、分野ごとの言葉','SHARED & DISTINCTIVE TERMS',fieldKeywords(report))}<div class="field-main-grid">${fieldPanel('出版数の予測シナリオ','EXISTING FORECAST',fieldForecast(report))}${fieldPanel('分野のつながりを裏付ける','CONNECTION EVIDENCE',fieldConnectionsEvidence(report))}</div><section class="panel field-narrative-panel">${panelHeader('分野の総合レポート','OBSERVATIONS → INTERPRETATION')}<div class="field-panel-body"><div class="field-interpretation"><div class="eyebrow">DEEPEN THE INTERPRETATION</div><div id="field-llm-controls">${fieldLLMControls()}</div></div><div id="field-generated-narrative">${fieldNarrative(report)}</div></div></section>${fieldPanel('根拠となる論文','TRACE BACK TO THE PAPERS',`<div class="field-evidence-grid">${evidenceList((report.evidence_papers||[]).map(p=>p.id),12)}</div><p class="field-help">ここには代表的な根拠を最大12件表示。根拠論文CSVには、選択分野と比較分野の全対象論文・全抄録を出力します。</p>`,`<button class="text-link" data-evidence-topic="${e(focus.id)}">選択分野の全論文 ${icon('arrow')}</button>`)}<details class="field-limitations"><summary>${icon('info')}この総合分析の限界と注意事項</summary>${fieldNotes(report.limitations)}</details>`;}
function returnToFieldReport(){if(!fieldCurrent())return;openDialog('#field-report-dialog');renderFieldReport();}
function addFieldReturnLink(){if(fieldCurrent()&&fieldState.report&&!$('#detail-body [data-action="field-return"]'))$('#detail-body').insertAdjacentHTML('afterbegin',`<button class="text-link field-back-link" data-action="field-return">← ${e(fieldState.report.focus.label)} の総合分析に戻る</button>`);}
function showFieldEvidence(ids,title,total=null){if(!fieldCurrent())return;const count=Math.max(ids.length,Number(total)||0);$('#detail-eyebrow').textContent='FIELD REPORT EVIDENCE';$('#detail-title').textContent=title||'総合分析の根拠';$('#detail-body').innerHTML=`${count>40?`<p class="field-help">全${num(count)}件のうち、この画面では最大40件を表示します。すべての保存済み根拠IDは分析データCSV、原典は根拠論文CSVで確認できます。</p>`:''}${evidenceList(ids,40)}`;addFieldReturnLink();openDialog('#detail-dialog');}
const actions={'paper-reload':()=>refreshPaperTable(),'paper-author-clear':()=>{state.paperAuthor=null;state.paperPage=0;render();},'author-network-refresh':()=>requestAuthorNetwork(authorNetworkState.groupBy,true),'author-cluster-clear':()=>{authorNetworkState.cluster=null;updateAuthorFilters();},'author-filter-clear':()=>{authorNetworkState.cluster=null;state.authorQuery='';const input=$('#author-search');if(input)input.value='';updateAuthorFilters();},'field-return':returnToFieldReport,'field-retry':()=>requestFieldReport(fieldState.provider||'none'),'field-llm-refresh':refreshFieldLLM,'field-legacy':()=>{closeDialogs();state.technologyTab='map';state.topic=fieldState.topicId;setView('technology');},'map-recent':()=>highlightRecent(),'clear-map-highlight':()=>{state.mapHighlight=null;render();},'recent-twelve':setRecentTwelve,'recent-search':async()=>{await showSourceHub();setRecentTwelve();},settings:async()=>{openDialog('#settings-dialog');try{await refreshStatus();}catch(error){message(error.message,true);}},upload:()=>showSourceHub(),'csv-upload':()=>showUpload(),'source-report':showSourceReport,'use-discovered':useDiscovered,datasets:showDatasets,analyze:runAnalysis,demo:loadDemo,export:showExport,methodology:showMethodology,insights:showInsights,'citation-upload':()=>showUpload('citations'),llm:()=>loadInsights(true,$('#insight-question')?.value||'',state.view!=='overview'),'local-insights':()=>loadInsights(false,'',state.view!=='overview')};
document.addEventListener('click',async event=>{const target=event.target.closest('button,a,[data-paper],[data-author],[data-topic],[data-author-cluster]');if(!target)return;if(target.hasAttribute('data-close')){target.closest('dialog').close();return;}if(target.hasAttribute('data-dismiss-notice')){$('#notice').hidden=true;return;}if(target.dataset.foresightTopic){window.AtlasForesight?.selectTopic(target.dataset.foresightTopic);closeDialogs();setView('foresight');return;}if(target.dataset.authorEvidence){try{const ids=JSON.parse(target.dataset.authorEvidence);if(Array.isArray(ids))showAuthorEvidence(ids);}catch{message('根拠の識別子を読み込めませんでした。',true);}return;}if(target.dataset.authorCluster){authorNetworkState.cluster=authorNetworkState.cluster===target.dataset.authorCluster?null:target.dataset.authorCluster;updateAuthorFilters();return;}if(target.dataset.fieldProvider){requestFieldReport(target.dataset.fieldProvider);return;}if(target.dataset.fieldChart){fieldState.chartMode=target.dataset.fieldChart;renderFieldReport();return;}if(target.dataset.fieldEvidence){try{const ids=JSON.parse(target.dataset.fieldEvidence);if(Array.isArray(ids))showFieldEvidence(ids,target.dataset.evidenceTitle,Number(target.dataset.evidenceTotal));}catch{message('根拠の識別子を読み込めませんでした。',true);}return;}if(target.dataset.technologyTab){state.technologyTab=target.dataset.technologyTab;render();return;}if(target.dataset.monthlyTopic){showMonthlyTopic(target.dataset.monthlyTopic);return;}if(target.dataset.monthlyMap){highlightRecent(target.dataset.monthlyMap);return;}if(target.dataset.sparseCandidate){state.sparseCandidate=target.dataset.sparseCandidate;render();return;}if(target.dataset.sparseEvidence){showSparseEvidence(target.dataset.sparseEvidence);return;}if(target.dataset.sparsePart){showSparseEvidence(state.sparseCandidate,target.dataset.sparsePart);return;}if(target.dataset.sparseMap){highlightSparse(target.dataset.sparseMap);return;}if(target.dataset.discoverMode){setDiscoveryMode(target.dataset.discoverMode);return;}if(target.dataset.sourceTab){setSourceTab(target.dataset.sourceTab);return;}if(target.dataset.action){event.preventDefault();actions[target.dataset.action]?.();return;}if(target.dataset.view){event.preventDefault();closeDialogs();setView(target.dataset.view);return;}if(target.dataset.detailTopic){openFieldReport(target.dataset.detailTopic);return;}if(target.dataset.topic){openFieldReport(target.dataset.topic);return;}if(target.dataset.forecastTopic){state.topic=target.dataset.forecastTopic;closeDialogs();setView('forecasts');return;}if(target.dataset.evidenceTopic){state.paperAuthor=null;state.paperTopic=target.dataset.evidenceTopic;state.paperPage=0;closeDialogs();setView('papers');return;}if(target.dataset.paper){const fromField=$('#field-report-dialog').open||Boolean($('#detail-body [data-action="field-return"]'));await showPaper(target.dataset.paper);if(fromField)addFieldReturnLink();return;}if(target.dataset.paperAuthor){state.paperAuthor=target.dataset.paperAuthor;state.query='';state.paperTopic='all';state.paperYear='all';state.paperPage=0;closeDialogs();setView('papers');return;}if(target.dataset.author){const fromField=$('#field-report-dialog').open||Boolean($('#detail-body [data-action="field-return"]'));showAuthor(target.dataset.author);if(fromField)addFieldReturnLink();return;}if(target.dataset.keyword){state.paperAuthor=null;state.query=target.dataset.keyword;state.paperTopic='all';state.paperYear='all';state.paperPage=0;setView('papers');return;}if(target.dataset.datasetAppend){openDatasetForAppend(target.dataset.datasetAppend);return;}if(target.dataset.dataset){const dataset=state.status.datasets.find(d=>d.id===target.dataset.dataset);if(dataset){state.dataset=dataset;applyDatasetAnalysisDefaults(dataset);updateDataset();closeDialogs();runAnalysis();}return;}if(target.dataset.uploadMode){state.uploadMode=target.dataset.uploadMode;updateUploadMode();return;}if(target.dataset.citationMode){state.citationMode=target.dataset.citationMode;render();return;}if(target.dataset.page){state.paperPage+=target.dataset.page==='next'?1:-1;refreshPaperTable();return;}if(target.dataset.mapZoom){state.mapZoom=target.dataset.mapZoom==='reset'?1:clamp(state.mapZoom+(target.dataset.mapZoom==='in'?.2:-.2),.6,2.4);const drawing=$('.map-drawing');const h=state.view==='technology'?500:350;if(drawing)drawing.setAttribute('transform',`translate(400 ${h/2}) scale(${state.mapZoom}) translate(-400 ${-h/2})`);}});
document.addEventListener('keydown',event=>{if(event.target.matches('[data-source-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const names=['public','csv','saved'],index=names.indexOf(event.target.dataset.sourceTab),next=event.key==='Home'?0:event.key==='End'?2:(index+(event.key==='ArrowRight'?1:2))%3;setSourceTab(names[next]);$('#source-tab-'+names[next]).focus();return;}if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="button"]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('input',event=>{if(event.target.id==='paper-search'){state.query=event.target.value;state.paperPage=0;refreshPaperTable(250);}if(event.target.id==='keyword-search'){state.keywordQuery=event.target.value;$('#keywords-table').innerHTML=keywordTable();}if(event.target.id==='author-search'){state.authorQuery=event.target.value;updateAuthorFilters();}});
document.addEventListener('change',event=>{if(event.target.id==='csv-after-import'){updateUploadMode(true);return;}if(event.target.id==='author-group-by'){requestAuthorNetwork(event.target.value);return;}if(event.target.id==='field-neighbor'){requestFieldReport('none',event.target.value||null);return;}if(event.target.id==='field-local-model'){fieldState.localModel=event.target.value;return;}if(event.target.id==='embedding'){state.kmeansEmbedding=event.target.value;syncModelControls();return;}if(['topic-model','sbert-model'].includes(event.target.id)){syncModelControls();return;}if(event.target.id==='source-provider'){renderProviderDescription();return;}if(event.target.id==='paper-topic')state.paperTopic=event.target.value;else if(event.target.id==='paper-year')state.paperYear=event.target.value;else if(event.target.id==='paper-sort')state.paperSort=event.target.value;else return;state.paperPage=0;refreshPaperTable();});
document.addEventListener('pointerover',event=>{const target=event.target.closest('[data-tooltip]');if(!target)return;const tip=$('#tooltip');tip.innerHTML=`<strong>${e(target.dataset.tooltip)}</strong><small>${e(target.dataset.tooltipSub||'')}</small>`;tip.hidden=false;const x=Math.min(event.clientX+14,window.innerWidth-305),y=Math.min(event.clientY+14,window.innerHeight-90);tip.style.left=`${Math.max(8,x)}px`;tip.style.top=`${Math.max(8,y)}px`;});
