window.addEventListener('atlas:connections-changed',()=>{if(state.status)state.status.llm_configured=false;fieldState.llm=null;++fieldState.llmRequest;const controls=$('#field-llm-controls');if(controls)controls.innerHTML=fieldLLMControls();const insightButton=$('[data-action="llm"]');if(insightButton)insightButton.disabled=true;$('#llm-status').textContent='接続設定を確認しています…';refreshStatus().then(()=>{if(insightButton)insightButton.disabled=!state.status?.llm_configured;}).catch(error=>{$('#llm-status').textContent='接続状態を確認できませんでした';message(error.message,true);});if(fieldCurrent())refreshFieldLLM();});
