$('#settings-form').addEventListener('submit',event=>{event.preventDefault();const o=readOptions(),err=$('#settings-error');err.hidden=true;const configError=modelConfigurationError();if(configError){err.textContent=configError;err.hidden=false;return;}if(o.anchor_month){const month=parseMonth(o.anchor_month);if(!month||month.year<o.start_year||month.year>o.end_year||o.anchor_month>latestCompleteMonth()){err.textContent='月次の基準月は分析対象年の範囲内、かつ完了した月までで指定してください。';err.hidden=false;return;}}if(o.start_year>o.end_year||o.end_year-o.start_year>=(state.status?.limits?.max_analysis_years||50)){err.textContent='分析期間は開始年から最大50年で指定してください。';err.hidden=false;return;}closeDialogs();runAnalysis();});
