$$('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
function parseRestoreLink(search){const params=new URLSearchParams(search);if(!params.has('result_id')&&!params.has('assessment_id'))return null;const resultId=params.get('result_id'),assessmentId=params.get('assessment_id');if(params.getAll('result_id').length!==1||params.getAll('assessment_id').length>1||!/^[a-f0-9]{32}$/i.test(resultId||'')||(params.has('assessment_id')&&!/^[a-f0-9]{32}$/i.test(assessmentId||'')))throw new Error('復元リンクの識別子が正しくありません。保存したリンク全体を開いてください。');const view=params.get('view')||(assessmentId?'foresight':'overview');if(!Object.hasOwn(viewLabels,view))throw new Error('復元リンクの画面が指定できません。');return {resultId,assessmentId,view};}
function clearRestoreLink(){try{const url=new URL(location.href);['result_id','assessment_id','view'].forEach(key=>url.searchParams.delete(key));window.history.replaceState(null,'',url.href);}catch{}}
function restoreResultOptions(result){const meta={...(result.meta||{}),...(result.options||{})},details=meta.topic_model_details||{},monthly=result.frontiers?.monthly||{};applyDatasetAnalysisDefaults(state.dataset);if(Number.isInteger(meta.start_year))$('#start-year').value=meta.start_year;if(Number.isInteger(meta.end_year))$('#end-year').value=meta.end_year;$('#monthly-anchor').value=Object.hasOwn(meta,'anchor_month')?(meta.anchor_month||''):(monthly.anchor_month||'');const windowMonths=meta.window_months??monthly.window_months;if([1,3,6].includes(windowMonths))$('#monthly-window').value=String(windowMonths);if(['kmeans','nmf','lda','bertopic'].includes(meta.topic_model))$('#topic-model').value=meta.topic_model;state.kmeansEmbedding=['sbert','transformer'].includes(meta.embedding)?'sbert':'tfidf';$('#embedding').value=state.kmeansEmbedding;const preset=meta.sbert_model||(String(meta.embedding_model||'').toLowerCase().includes('minilm')?'multilingual_minilm':'mpnet');if(['mpnet','multilingual_minilm'].includes(preset))$('#sbert-model').value=preset;const topicCount=meta.n_topics??details.requested_topics;if(Number.isInteger(topicCount)&&topicCount>=2&&topicCount<=20)$('#topic-count').value=String(topicCount);if(Number.isInteger(meta.horizon??meta.forecast_horizon))$('#forecast-horizon').value=String(meta.horizon??meta.forecast_horizon);if(Number.isInteger(details.min_topic_size??meta.min_topic_size))$('#min-topic-size').value=String(details.min_topic_size??meta.min_topic_size);syncModelControls();}
async function restoreAnalysisLink(link){const selection=++state.selectionVersion,run=++state.run;showLoading('保存された分析結果を確認しています');const current=()=>selection===state.selectionVersion&&run===state.run;const result=await api(`/api/results/${encodeURIComponent(link.resultId)}?view=summary`).catch(error=>{if(current())throw error;return null;});if(!current())return;if(result.id!==link.resultId||!Array.isArray(result.topics)||!Array.isArray(result.papers))throw new Error('保存された分析結果を確認できませんでした。');const dataset=state.status.datasets.find(item=>item.id===result.dataset_id);if(!dataset)throw new Error('この分析の元データが見つかりません。保存データを確認してください。');if(link.assessmentId&&!window.AtlasForesight?.restoreFromLink)throw new Error('探索画面を読み込めませんでした。再読み込みしてください。');resetFieldReport();resetAuthorNetwork();state.dataset=dataset;state.result=result;state.insight=null;state.insightBusy=false;state.mapZoom=1;updateDataset();restoreResultOptions(result);window.dispatchEvent(new CustomEvent('atlas:result',{detail:result}));state.topic=classifiedTopics()[0]?.id||result.topics[0]?.id;resetFilters();state.view=link.view;if(link.assessmentId){showLoading('保存された評価と分析の対応を確認しています');const restored=await window.AtlasForesight.restoreFromLink(result,link.assessmentId);if(!current())return;if(!restored)state.view='foresight';}$('#analysis-time').textContent='保存結果を復元';$('#embedding-label').textContent=analysisMethodLabel(result.meta);$('#embedding-label').title=`テーマ抽出：${topicModelName(result.meta.topic_model)} / マップ：${mapRepresentationLabel(result.meta)}`;$('#period-label').textContent=`${result.meta.start_year} — ${result.meta.end_year}`;$('#demo-badge').hidden=!result.meta.is_demo;render();renderWarnings();renderSourceNotice();loadInsights(false);}
function showRestoreError(error){$('#analysis-time').textContent='復元エラー';$('#content').innerHTML=empty('保存した分析を復元できませんでした',error.message,`<button class="button button-primary" data-action="datasets">保存データを開く</button> <button class="button button-quiet" data-action="demo">合成デモを開く</button>`);}
async function init(){hydrateIcons();showLoading();let restoring=false;try{restoring=new URLSearchParams(location.search).has('result_id')||new URLSearchParams(location.search).has('assessment_id');const link=parseRestoreLink(location.search);await refreshStatus();$('#start-year').value=state.status.default_start_year;$('#end-year').value=state.status.default_end_year;$('#monthly-anchor').max=latestCompleteMonth();if(link)await restoreAnalysisLink(link);else await loadDemo();}catch(error){if(restoring)showRestoreError(error);else showError(error);}}
init();
